  auto create_result = drop_result
      .and_then(create_table<Product>);

  if (!create_result) {
    return false;
  }

  // Begin transaction, insert products, and commit
  auto transaction_result = create_result
      .and_then(begin_transaction)
      .and_then(insert(std::ref(products)))
      .and_then(commit);

  // Return true if the transaction succeeded, false otherwise
  return static_cast<bool>(transaction_result);
}

