namespace delete_inactive_users {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
  std::optional<sqlgen::DateTime> last_login;
  std::string status = "active";
};

int delete_inactive_users() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn = sqlite::connect("test_db.sqlite");

  // Begin a transaction for safety
  auto transaction = conn | begin_transaction;

  // Delete users who have not logged in since 2025-01-01
  // Using the comparison operator < on the last_login column
  auto cutoff_date = DateTime("2025-01-01 00:00:00");
  auto result = transaction
    | delete_from<User> | where("last_login"_c < cutoff_date)
    | commit;

  // Return 0 on success, -1 on error
  if (result) {
    return 0;
  } else {
    return -1;
  }
}

} // namespace delete_inactive_users
```

## Explanation:

1. **Connect to database**: Uses `sqlite::connect("test_db.sqlite")` to connect to the SQLite database file.

2. **Begin transaction**: Uses the pipe operator `|` with `begin_transaction` to start a transaction for data safety.

3. **Delete operation**: 
   - Uses `delete_from<User>` to create a DELETE statement for the User table
   - Pipes it with `where("last_login"_c < cutoff_date)` to filter users whose `last_login` is before 2025-01-01
   - The `"last_login"_c` literal creates a column reference using the `_c` suffix from `sqlgen::literals`

4. **Commit**: Pipes the delete operation with `commit` to commit the transaction

5. **Return result**: Returns 0 on success (when `result` evaluates to true), -1 on error

The implementation uses the fluent pipe-based API of `sqlgen` to chain operations together in a type-safe manner.

