1	#ifndef SQLGEN_COMMIT_HPP_
2	#define SQLGEN_COMMIT_HPP_
3	
4	#include <type_traits>
5	
6	#include "Ref.hpp"
7	#include "Result.hpp"
8	#include "Transaction.hpp"
9	
10	namespace sqlgen {
11	
12	template <class Connection>
13	  requires is_connection<Connection>
14	Result<Ref<Connection>> commit_impl(const Ref<Transaction<Connection>>& _t) {
15	  return _t->commit().transform([&](const auto&) { return _t->conn(); });
16	}
17	
18	template <class Connection>
19	  requires is_connection<Connection>
20	Result<Ref<Connection>> commit_impl(
21	    const Result<Transaction<Connection>>& _res) {
22	  return _res.and_then([&](const auto& _t) { return commit_impl(_t); });
23	}
24	
25	struct Commit {
26	  auto operator()(const auto& _conn) const { return commit_impl(_conn); }
27	};
28	
29	inline const auto commit = Commit{};
30	
31	}  // namespace sqlgen
32	
33	#endif
34

1	#ifndef SQLGEN_BEGIN_TRANSACTION_HPP_
2	#define SQLGEN_BEGIN_TRANSACTION_HPP_
3	
4	#include <type_traits>
5	
6	#include "Ref.hpp"
7	#include "Result.hpp"
8	#include "Transaction.hpp"
9	#include "is_connection.hpp"
10	
11	namespace sqlgen {
12	
13	template <class Connection>
14	  requires is_connection<Connection>
15	Result<Ref<Transaction<Connection>>> begin_transaction_impl(
16	    const Ref<Connection>& _conn) {
17	  return _conn->begin_transaction().transform(
18	      [&](const auto&) { return Ref<Transaction<Connection>>::make(_conn); });
19	}
20	
21	template <class Connection>
22	  requires is_connection<Connection>
23	Result<Ref<Transaction<Connection>>> begin_transaction_impl(
24	    const Result<Ref<Connection>>& _res) {
25	  return _res.and_then(
26	      [&](const auto& _conn) { return begin_transaction_impl(_conn); });
27	}
28	
29	struct BeginTransaction {
30	  auto operator()(const auto& _conn) const {
31	    return begin_transaction_impl(_conn);
32	  }
33	};
34	
35	inline const auto begin_transaction = BeginTransaction{};
36	
37	}  // namespace sqlgen
38	
39	#endif
