1	#ifndef SQLGEN_DELETE_FROM_HPP_
2	#define SQLGEN_DELETE_FROM_HPP_
3	
4	#include <type_traits>
5	
6	#include "Ref.hpp"
7	#include "Result.hpp"
8	#include "is_connection.hpp"
9	#include "transpilation/to_delete_from.hpp"
10	#include "where.hpp"
11	
12	namespace sqlgen {
13	
14	template <class ValueType, class WhereType, class Connection>
15	  requires is_connection<Connection>
16	Result<Ref<Connection>> delete_from_impl(const Ref<Connection>& _conn,
17	                                         const WhereType& _where) {
18	  const auto query =
19	      transpilation::to_delete_from<ValueType, WhereType>(_where);
20	  return _conn->execute(_conn->to_sql(query)).transform([&](const auto&) {
21	    return _conn;
22	  });
23	}
24	
25	template <class ValueType, class WhereType, class Connection>
26	  requires is_connection<Connection>
27	Result<Ref<Connection>> delete_from_impl(const Result<Ref<Connection>>& _res,
28	                                         const WhereType& _where) {
29	  return _res.and_then([&](const auto& _conn) {
30	    return delete_from_impl<ValueType, WhereType>(_conn, _where);
31	  });
32	}
33	
34	template <class ValueType, class WhereType = Nothing>
35	struct DeleteFrom {
36	  auto operator()(const auto& _conn) const {
37	    return delete_from_impl<ValueType, WhereType>(_conn, where_);
38	  }
39	
40	  template <class ConditionType>
41	  friend auto operator|(const DeleteFrom<ValueType, WhereType>& _d,
42	                        const Where<ConditionType>& _where) {
43	    static_assert(std::is_same_v<WhereType, Nothing>,
44	                  "You cannot call where(...) twice (but you can apply more "
45	                  "than one condition by combining them with && or ||).");
46	    return DeleteFrom<ValueType, ConditionType>{.where_ = _where.condition};
47	  }
48	
49	  WhereType where_;
50	};
51	
52	template <class ContainerType>
53	const auto delete_from = DeleteFrom<ContainerType>{};
54	
55	}  // namespace sqlgen
56	
57	#endif
