3	
4	#include <type_traits>
5	
6	namespace sqlgen {
7	
8	template <class ConditionType>
9	struct Where {
10	  ConditionType condition;
11	};
12	
13	template <class ConditionType>
14	inline auto where(const ConditionType& _cond) {
15	  return Where<std::remove_cvref_t<ConditionType>>{.condition = _cond};
16	};
17	
18	}  // namespace sqlgen
19	
20	#endif
