30	      std::is_same_v<
31	          std::remove_cvref_t<transpilation::remove_reflection_t<T>>,
32	          std::remove_cvref_t<
33	              transpilation::remove_reflection_t<transpilation::underlying_t<
34	                  ForeignTableType, transpilation::Col<_col_name>>>>>,
35	      "The type of the column and the type of the referenced column must be "
36	      "the same.");
37	  static_assert(
38	      transpilation::is_primary_key_v<
39	          std::remove_cvref_t<rfl::field_type_t<_col_name, ForeignTableType>>>,
40	      "The referenced column must be a primary key.");
41	
42	  ForeignKey() : value_(T()) {}
43	
44	  ForeignKey(const T& _value) : value_(_value) {}
45	
46	  ForeignKey(ForeignKey&& _other) noexcept = default;
