52	                                    bool>::type = true>
53	  ForeignKey(const U& _value) : value_(_value) {}
54	
55	  template <class U,
56	            typename std::enable_if<std::is_convertible_v<U, ReflectionType>,
57	                                    bool>::type = true>
58	  ForeignKey(U&& _value) noexcept : value_(std::forward<U>(_value)) {}
59	
60	  ~ForeignKey() = default;
61	
62	  /// Returns the underlying object.
63	  ReflectionType& get() { return value_; }
64	
65	  /// Returns the underlying object.
66	  const ReflectionType& get() const { return value_; }
67	
68	  /// Returns the underlying object.
69	  ReflectionType& operator()() { return value_; }
70	
71	  /// Returns the underlying object.
72	  const ReflectionType& operator()() const { return value_; }
73	
74	  /// Assigns the underlying object.
75	  auto& operator=(const ReflectionType& _value) {
76	    value_ = _value;
77	    return *this;
78	  }
79	
80	  /// Assigns the underlying object.
81	  template <class U,
82	            typename std::enable_if<std::is_convertible_v<U, ReflectionType>,
83	                                    bool>::type = true>
84	  auto& operator=(const U& _value) {
85	    value_ = _value;
86	    return *this;
87	  }
88	
89	  /// Assigns the underlying object.
90	  ForeignKey& operator=(const ForeignKey& _other) = default;
91	
92	  /// Assigns the underlying object.
93	  ForeignKey& operator=(ForeignKey&& _other) = default;
94	
95	  /// Necessary for the automated transpilation to work.
96	  const T& reflection() const { return value_; }
97	
98	  /// Assigns the underlying object.
99	  void set(const T& _value) { value_ = _value; }
100	
101	  /// Returns the underlying object.
102	  T& value() { return value_; }
103	
104	  /// Returns the underlying object.
105	  const T& value() const { return value_; }
106	
107	  /// The underlying value.
