Looking at the `sqlgen` library API and the requirements, I need to:
1. Connect to the SQLite database
2. Create the User and Post tables
3. Build a query with an inner join and date filtering
4. Execute and return the results

Here's the complete file:

```cpp
#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <chrono>
#include <iomanip>
#include <sstream>

namespace query_active_users_posts {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct Post {
  sqlgen::PrimaryKey<int> post_id;
  int user_id;
  sqlgen::DateTime created_at;
};

struct ActiveUser {
  static constexpr const char* tablename = "ActiveUserView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

std::vector<ActiveUser> query_active_users_posts() {
    using namespace sqlgen::literals;

    // Connect to database
    auto db = sqlgen::sqlite::connect("test_db.sqlite");

    // Create tables
    sqlgen::create_table<User>()(db);
    sqlgen::create_table<Post>()(db);

    // Define table aliases
    auto u = "u"_t1;
    auto p = "p"_t2;

    // Build and execute query
    return (
        sqlgen::select_from<User>(u)
        | sqlgen::inner_join<Post>(p, sqlgen::col<&User::user_id>(u) == sqlgen::col<&Post::user_id>(p))
        | sqlgen::where(
            sqlgen::col<&Post::created_at>(p) >= "2025-12-01" &&
            sqlgen::col<&Post::created_at>(p) <= "2025-12-31"
        )
        | sqlgen::read<ActiveUser>()
    )(db);
}

}  // namespace query_active_users_posts
```

This implementation:
- Uses `sqlgen::sqlite::connect()` to connect to the database
- Creates both tables using `sqlgen::create_table<T>()`
- Uses table aliases (`"u"_t1` and `"p"_t2`) for the query
- Performs an `inner_join` between User and Post tables on `user_id`
- Filters posts with `created_at` between the specified dates using the `where` clause
- Returns the results as `std::vector<ActiveUser>` using `read<ActiveUser>()`

