#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace query_course_enrollment_stats {

struct Course {
  sqlgen::PrimaryKey<int> course_id;
  std::string title;
};

struct Enrollment {
  sqlgen::PrimaryKey<int> enrollment_id;
  sqlgen::ForeignKey<int, Course, "course_id"> course_id;
  std::optional<float> grade;
};

struct CourseStats {
  std::string title;
  int student_count;
  std::optional<double> avg_grade;
};

struct CourseStatsView {
  // View to store course enrollment statistics
};

/**
 * Function: Calculate enrollment statistics per course.
 *
 * @return List of course statistics
 */
std::vector<CourseStats> query_course_enrollment_stats() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Sample data for testing
  const auto courses = std::vector<Course>({
      Course{.course_id = 1, .title = "Mathematics"},
      Course{.course_id = 2, .title = "Physics"},
      Course{.course_id = 3, .title = "Chemistry"}
  });

  const auto enrollments = std::vector<Enrollment>({
      Enrollment{.enrollment_id = 1, .course_id = 1, .grade = 85.0f},
      Enrollment{.enrollment_id = 2, .course_id = 1, .grade = 90.0f},
      Enrollment{.enrollment_id = 3, .course_id = 1, .grade = std::nullopt},
      Enrollment{.enrollment_id = 4, .course_id = 2, .grade = 75.0f},
      Enrollment{.enrollment_id = 5, .course_id = 2, .grade = 80.0f},
      Enrollment{.enrollment_id = 6, .course_id = 3, .grade = std::nullopt}
  });

  // Query: SELECT c.title, COUNT(e.enrollment_id) as student_count, AVG(e.grade) as avg_grade
  // FROM Course c
  // LEFT JOIN Enrollment e ON c.course_id = e.course_id
  // GROUP BY c.course_id, c.title;
  const auto query_stats =
      select_from<Course, "c">(
          "title"_c,
          count("enrollment_id"_e) | as<"student_count">,
          avg("grade"_e) | as<"avg_grade">) |
      left_join<Enrollment, "e">("course_id"_c == "course_id"_e) |
      group_by("course_id"_c, "title"_c) |
      to<std::vector<CourseStats>>;

  // Connect to database, create tables, insert data, and execute query
  const auto results = sqlite::connect("test_db.sqlite")
                          .and_then(write(std::ref(courses)))
                          .and_then(write(std::ref(enrollments)))
                          .and_then(query_stats)
                          .value();

  return results;
}

}  // namespace query_course_enrollment_stats
```

