11	template <class ValueType, class Connection>
12	  requires is_connection<Connection>
13	Result<Ref<Connection>> create_table_impl(const Ref<Connection>& _conn,
14	                                          const bool _if_not_exists) {
15	  const auto query = transpilation::to_create_table<ValueType>(_if_not_exists);
16	  return _conn->execute(_conn->to_sql(query)).transform([&](const auto&) {
17	    return _conn;
18	  });
19	}
20	
21	template <class ValueType, class Connection>
22	  requires is_connection<Connection>
23	Result<Ref<Connection>> create_table_impl(const Result<Ref<Connection>>& _res,
24	                                          const bool _if_not_exists) {
25	  return _res.and_then([&](const auto& _conn) {
26	    return create_table_impl<ValueType>(_conn, _if_not_exists);
27	  });
28	}
