13	struct Person {
14	  sqlgen::PrimaryKey<uint32_t, sqlgen::auto_incr> id;
15	  std::string first_name;
16	  std::string last_name;
17	  sqlgen::Date birthday;
18	};
19	
20	TEST(sqlite, test_range_select_from_with_timestamps) {
21	  const auto people1 =
22	      std::vector<Person>({Person{.first_name = "Homer",
23	                                  .last_name = "Simpson",
24	                                  .birthday = sqlgen::Date("1970-01-01")},
25	                           Person{.first_name = "Bart",
26	                                  .last_name = "Simpson",
27	                                  .birthday = sqlgen::Date("2000-01-01")},
28	                           Person{.first_name = "Lisa",
29	                                  .last_name = "Simpson",
30	                                  .birthday = sqlgen::Date("2002-01-01")},
31	                           Person{.first_name = "Maggie",
32	                                  .last_name = "Simpson",
33	                                  .birthday = sqlgen::Date("2010-01-01")}});
34	
35	  using namespace sqlgen;
36	  using namespace sqlgen::literals;
37	
38	  struct Birthday {
39	    Date birthday;
40	    Date birthday_recreated;
41	    time_t birthday_unixepoch;
42	    double age_in_days;
43	    int hour;
44	    int minute;
45	    int second;
46	    int weekday;
47	  };
48	
49	  const auto get_birthdays =
50	      select_from<Person>(
51	          ("birthday"_c + std::chrono::days(10)) | as<"birthday">,
52	          ((cast<Date>(concat(cast<std::string>(year("birthday"_c)), "-",
53	                              cast<std::string>(month("birthday"_c)), "-",
54	                              cast<std::string>(day("birthday"_c)))))) |
55	              as<"birthday_recreated">,
56	          days_between("birthday"_c, Date("2011-01-01")) | as<"age_in_days">,
57	          unixepoch("birthday"_c + std::chrono::days(10)) |
58	              as<"birthday_unixepoch">,
59	          hour("birthday"_c) | as<"hour">, minute("birthday"_c) | as<"minute">,
60	          second("birthday"_c) | as<"second">,
61	          weekday("birthday"_c) | as<"weekday">) |
62	      order_by("id"_c) | to<std::vector<Birthday>>;
63	
64	  const auto birthdays = sqlite::connect()
65	                             .and_then(write(std::ref(people1)))
66	                             .and_then(get_birthdays)
67	                             .value();
68	
69	  const std::string expected_query =
70	      R"(SELECT datetime("birthday", '+10 days') AS "birthday", cast((cast(cast(strftime('%Y', "birthday") as INT) as TEXT) || '-' || cast(cast(strftime('%m', "birthday") as INT) as TEXT) || '-' || cast(cast(strftime('%d', "birthday") as INT) as TEXT)) as TEXT) AS "birthday_recreated", julianday('2011-01-01') - julianday("birthday") AS "age_in_days", unixepoch(datetime("birthday", '+10 days'), 'subsec') AS "birthday_unixepoch", cast(strftime('%H', "birthday") as INT) AS "hour", cast(strftime('%M', "birthday") as INT) AS "minute", cast(strftime('%S', "birthday") as INT) AS "second", cast(strftime('%w', "birthday") as INT) AS "weekday" FROM "Person" ORDER BY "id")";
71	  const std::string expected =
72	      R"([{"birthday":"1970-01-11","birthday_recreated":"1970-01-01","birthday_unixepoch":864000,"age_in_days":14975.0,"hour":0,"minute":0,"second":0,"weekday":4},{"birthday":"2000-01-11","birthday_recreated":"2000-01-01","birthday_unixepoch":947548800,"age_in_days":4018.0,"hour":0,"minute":0,"second":0,"weekday":6},{"birthday":"2002-01-11","birthday_recreated":"2002-01-01","birthday_unixepoch":1010707200,"age_in_days":3287.0,"hour":0,"minute":0,"second":0,"weekday":2},{"birthday":"2010-01-11","birthday_recreated":"2010-01-01","birthday_unixepoch":1263168000,"age_in_days":365.0,"hour":0,"minute":0,"second":0,"weekday":5}])";
73	
74	  EXPECT_EQ(sqlite::to_sql(get_birthdays), expected_query);
75	  EXPECT_EQ(rfl::json::write(birthdays), expected);
76	}
77	
78	}  // namespace test_range_select_from_with_timestamps
