  static constexpr const char* tablename = "DailyTrafficView";
  static constexpr bool is_view = true;
  std::string visit_date;
  int total_visits;
  int unique_pages;
};

/**
 * Function: Calculate daily traffic metrics from a log table.
 * 
 * @return List of daily traffic metrics
 */
std::vector<DailyTraffic> query_daily_traffic_metrics() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Build the query:
  // SELECT strftime('%Y-%m-%d', visit_time) as visit_date, 
  //        COUNT(*) as total_visits, 
  //        COUNT(DISTINCT url) as unique_pages
  // FROM PageVisit
  // GROUP BY visit_date
  // ORDER BY visit_date;

  auto query = select_from<PageVisit>(
      // Create visit_date by concatenating year, month, and day
      concat(
          cast<std::string>(year("visit_time"_c)), 
          "-",
          cast<std::string>(month("visit_time"_c)), 
          "-",
          cast<std::string>(day("visit_time"_c))
      ) | as<"visit_date">,
      // Count total visits
      count() | as<"total_visits">,
      // Count unique URLs
      count_distinct("url"_c) | as<"unique_pages">
  ) 
  | group_by("visit_date"_c)
  | order_by("visit_date"_c)
  | to<std::vector<DailyTraffic>>;

  // Execute the query and return the results
  return conn.and_then(query).value();
}

}  // namespace query_daily_traffic_metrics
