  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

std::vector<OrderView> query_high_value_orders() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  const auto query =
      select_from<Order, "o">(
          "order_id"_t1 | as<"order_id">,
          "name"_t2 | as<"name">,
          "total_amount"_t1 | as<"total_amount">,
          "order_date"_t1 | as<"order_date">) |
      inner_join<Customer, "c">("customer_id"_t1 == "customer_id"_t2) |
      where("total_amount"_t1 > 1000.0) |
      order_by("total_amount"_t1.desc()) |
      to<std::vector<OrderView>>;

  auto conn = sqlite::connect("test_db.sqlite");
  return query(conn).value();
}

}  // namespace query_high_value_orders
```

## Explanation:

1. **Table Aliases**: 
   - `select_from<Order, "o">` creates an alias "o" for the Order table (referred to as `_t1`)
   - `inner_join<Customer, "c">` creates an alias "c" for the Customer table (referred to as `_t2`)

2. **Select Columns**:
   - `"order_id"_t1` - order_id from Order table
   - `"name"_t2` - name from Customer table
   - `"total_amount"_t1` - total_amount from Order table
   - `"order_date"_t1` - order_date from Order table
   - Each is aliased using `as<"...">` to match the OrderView struct fields

3. **Inner Join**: 
   - `inner_join<Customer, "c">("customer_id"_t1 == "customer_id"_t2)` joins Order with Customer on customer_id

4. **Where Clause**: 
   - `where("total_amount"_t1 > 1000.0)` filters orders with total_amount > 1000

5. **Order By**: 
   - `order_by("total_amount"_t1.desc())` orders by total_amount in descending order

6. **Convert to Vector**: 
   - `to<std::vector<OrderView>>` specifies the return type

7. **Execute Query**: 
   - `sqlite::connect("test_db.sqlite")` connects to the database
   - `query(conn).value()` executes the query and extracts the value

This generates the SQL equivalent to:
```sql
SELECT o.order_id AS order_id, c.name AS name, o.total_amount AS total_amount, o.order_date AS order_date
FROM "Order" o
INNER JOIN Customer c ON o.customer_id = c.customer_id
WHERE o.total_amount > 1000.0
ORDER BY o.total_amount DESC;
```

