27	           .id = 3, .first_name = "Maggie", .last_name = "Simpson", .age = 0}});
28	
29	  using namespace sqlgen;
30	  using namespace sqlgen::literals;
31	
32	  struct Children {
33	    std::string last_name;
34	    int num_children;
35	    int num_last_names;
36	    double avg_age;
37	    double max_age;
38	    double min_age;
39	    double sum_age;
40	  };
