namespace query_search_books_by_criteria {

struct Book {
  sqlgen::PrimaryKey<int> book_id;
  std::string title;
  std::string author;
  int year;
  std::string genre;
  double price;
};

struct BookFilters {
  std::optional<std::string> title_keyword;
  std::optional<int> min_year;
  std::optional<std::string> genre;
  std::optional<double> max_price;
};

/**
 * Function: Search for books based on multiple optional criteria.
 *
 * @param filters Optional filters for title, year, genre, and price
 * @return List of books matching the criteria
 */
std::vector<Book> query_search_books_by_criteria(const BookFilters& filters) {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Connect to the database
    auto conn = sqlite::connect("test_db.sqlite");
    if (!conn) {
        return {};  // Return empty vector on connection failure
    }

    // Build the base query
    auto query = select_from<Book>();

    // Dynamically construct the WHERE clause based on provided filters
    if (filters.title_keyword && filters.min_year && filters.genre && filters.max_price) {
        // All filters provided
        auto result = (query |
                      where("title"_c.like("%" + *filters.title_keyword + "%") &&
                            "year"_c >= *filters.min_year &&
                            "genre"_c == *filters.genre &&
                            "price"_c <= *filters.max_price) |
                      to<std::vector<Book>>)(conn);
        return result.value_or(std::vector<Book>{});
    } else if (filters.title_keyword && filters.min_year && filters.genre) {
        // title_keyword, min_year, genre
        auto result = (query |
                      where("title"_c.like("%" + *filters.title_keyword + "%") &&
                            "year"_c >= *filters.min_year &&
                            "genre"_c == *filters.genre) |
                      to<std::vector<Book>>)(conn);
        return result.value_or(std::vector<Book>{});
    } else if (filters.title_keyword && filters.min_year && filters.max_price) {
        // title_keyword, min_year, max_price
        auto result = (query |
                      where("title"_c.like("%" + *filters.title_keyword + "%") &&
                            "year"_c >= *filters.min_year &&
                            "price"_c <= *filters.max_price) |
                      to<std::vector<Book>>)(conn);
        return result.value_or(std::vector<Book>{});
    } else if (filters.title_keyword && filters.genre && filters.max_price) {
        // title_keyword, genre, max_price
        auto result = (query |
                      where("title"_c.like("%" + *filters.title_keyword + "%") &&
                            "genre"_c == *filters.genre &&
                            "price"_c <= *filters.max_price) |
                      to<std::vector<Book>>)(conn);
        return result.value_or(std::vector<Book>{});
    } else if (filters.min_year && filters.genre && filters.max_price) {
        // min_year, genre, max_price
        auto result = (query |
                      where("year"_c >= *filters.min_year &&
                            "genre"_c == *filters.genre &&
                            "price"_c <= *filters.max_price) |
                      to<std::vector<Book>>)(conn);
        return result.value_or(std::vector<Book>{});
    } else if (filters.title_keyword && filters.min_year) {
        // title_keyword, min_year
        auto result = (query |
                      where("title"_c.like("%" + *filters.title_keyword + "%") &&
                            "year"_c >= *filters.min_year) |
                      to<std::vector<Book>>)(conn);
        return result.value_or(std::vector<Book>{});
    } else if (filters.title_keyword && filters.genre) {
        // title_keyword, genre
        auto result = (query |
                      where("title"_c.like("%" + *filters.title_keyword + "%") &&
                            "genre"_c == *filters.genre) |
                      to<std::vector<Book>>)(conn);
        return result.value_or(std::vector<Book>{});
    } else if (filters.title_keyword && filters.max_price) {
        // title_keyword, max_price
        auto result = (query |
                      where("title"_c.like("%" + *filters.title_keyword + "%") &&
                            "price"_c <= *filters.max_price) |
                      to<std::vector<Book>>)(conn);
        return result.value_or(std::vector<Book>{});
    } else if (filters.min_year && filters.genre) {
        // min_year, genre
        auto result = (query |
                      where("year"_c >= *filters.min_year &&
                            "genre"_c == *filters.genre) |
                      to<std::vector<Book>>)(conn);
        return result.value_or(std::vector<Book>{});
    } else if (filters.min_year && filters.max_price) {
        // min_year, max_price
        auto result = (query |
                      where("year"_c >= *filters.min_year &&
                            "price"_c <= *filters.max_price) |
                      to<std::vector<Book>>)(conn);
        return result.value_or(std::vector<Book>{});
    } else if (filters.genre && filters.max_price) {
        // genre, max_price
        auto result = (query |
                      where("genre"_c == *filters.genre &&
                            "price"_c <= *filters.max_price) |
                      to<std::vector<Book>>)(conn);
        return result.value_or(std::vector<Book>{});
    } else if (filters.title_keyword) {
        // Only title_keyword
        auto result = (query |
                      where("title"_c.like("%" + *filters.title_keyword + "%")) |
                      to<std::vector<Book>>)(conn);
        return result.value_or(std::vector<Book>{});
    } else if (filters.min_year) {
        // Only min_year
        auto result = (query |
                      where("year"_c >= *filters.min_year) |
                      to<std::vector<Book>>)(conn);
        return result.value_or(std::vector<Book>{});
    } else if (filters.genre) {
        // Only genre
        auto result = (query |
                      where("genre"_c == *filters.genre) |
                      to<std::vector<Book>>)(conn);
        return result.value_or(std::vector<Book>{});
    } else if (filters.max_price) {
        // Only max_price
        auto result = (query |
                      where("price"_c <= *filters.max_price) |
                      to<std::vector<Book>>)(conn);
        return result.value_or(std::vector<Book>{});
    } else {
        // No filters - return all books
        auto result = (query | to<std::vector<Book>>)(conn);
        return result.value_or(std::vector<Book>{});
    }
}

}  // namespace query_search_books_by_criteria

