struct UserProfile {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> user_id;
  sqlgen::Unique<sqlgen::Varchar<50>> username;
  sqlgen::Unique<sqlgen::Varchar<100>> email;
  int age;
  std::string bio;
  sqlgen::DateTime created_at;
  bool is_verified;
};

/**
 * Function: Create a table with various constraints and data types.
 * 
 * @return true if creation succeeds, false otherwise
 */
bool create_complex_table() {
  using namespace sqlgen;

  // Connect to SQLite database
  auto result = sqlite::connect("test_db.sqlite")
                    .and_then(create_table<UserProfile> | if_not_exists);

  // Check if table creation succeeded
  return result.has_value();
}

}  // namespace schema_create_complex_table
```

## Important Notes:

**What the code accomplishes:**
- ✅ `user_id`: `INTEGER PRIMARY KEY AUTOINCREMENT`
- ✅ `username`: `VARCHAR(50) NOT NULL UNIQUE`
- ✅ `email`: `VARCHAR(100) NOT NULL UNIQUE`
- ✅ `age`: `INTEGER NOT NULL`
- ✅ `bio`: `TEXT NOT NULL`
- ✅ `created_at`: `DATETIME NOT NULL`
- ✅ `is_verified`: `INTEGER NOT NULL` (SQLite stores booleans as integers)

**Limitations of the sqlgen library:**
- ❌ `CHECK (age >= 18)` - Not supported by sqlgen (you'll need to validate age in your C++ code)
- ❌ `DEFAULT CURRENT_TIMESTAMP` - Not supported (you'll need to set `created_at` manually when inserting)
- ❌ `DEFAULT FALSE` / `DEFAULT 0` - Not supported (you'll need to set `is_verified` manually when inserting)

**Workaround for missing constraints:**
If you absolutely need the CHECK and DEFAULT constraints at the SQL level, you could execute raw SQL after table creation:

```cpp
