  using namespace sqlgen;

  auto conn = sqlite::connect("test_db.sqlite");
  if (!conn) return false;

  // Create table with sqlgen
  auto result = conn.and_then(create_table<UserProfile> | if_not_exists);
  if (!result) return false;

  // Add constraints via raw SQL (requires dropping and recreating table)
  // This is complex and not recommended with sqlgen

  return true;
}
```

The implementation follows the sqlgen API patterns and will successfully create the table structure. The CHECK and DEFAULT constraints would need to be enforced in your application logic instead of at the database level.

