    sqlgen::Varchar<20> sku;
    sqlgen::Varchar<100> name;
    sqlgen::Varchar<50> category;
    double price;
  };

  bool manage_indexes() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Connect to SQLite database and create table with indexes
    auto result = sqlgen::sqlite::connect("test_db.sqlite")
                      .and_then(create_table<Product> | if_not_exists)
                      .and_then(create_index<"idx_product_category", Product>(
