                      .and_then(create_unique_index<"idx_product_sku", Product>(
                                    "sku"_c) |
                                if_not_exists)
                      .and_then(create_index<"idx_product_name_price", Product>(
                                    "name"_c, "price"_c) |
                                if_not_exists);

    // Return true if successful, false otherwise
    return result.has_value();
  }

}  // namespace schema_manage_indexes
