#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace schema_migration_add_column {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct UserAfter {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> user_id;
  std::string username;
  std::string phone_number;
  bool is_active;
};

/**
 * Function: Perform schema migration to add new columns.
 *
 * @return true if migration succeeds, false otherwise
 */
bool migration_add_column() {
  using namespace sqlgen;

  // Connect to SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Attempt to add phone_number column
  // Note: SQLite stores booleans as INTEGER (0 or 1)
  auto result = conn
      .and_then(exec("ALTER TABLE User ADD COLUMN phone_number VARCHAR(20);"))
      .and_then(exec("ALTER TABLE User ADD COLUMN is_active INTEGER DEFAULT 1;"));

  // Check if the migration succeeded
  if (result.error()) {
    // Check if the error is because the column already exists
    // SQLite will return an error if column already exists
    const auto error_msg = result.error().value().what();
    std::string error_str(error_msg);

    // If error is "duplicate column name", consider it a success
    // (migration already applied)
    if (error_str.find("duplicate column") != std::string::npos) {
      return true;
    }

    // Otherwise, migration failed
    return false;
  }

  // Migration succeeded
  return true;
}

} // namespace schema_migration_add_column

