#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace transaction_transfer_funds {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
};

bool transfer_funds(int from_account_id, int to_account_id, double amount) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the database
  auto conn = sqlite::connect("test_db.sqlite");
  if (!conn) {
    return false;
  }

  // Begin transaction
  auto transaction = begin_transaction(conn);
  if (!transaction) {
    return false;
  }

  // Update sender's account: deduct amount and verify sufficient funds
  // The WHERE clause ensures balance >= amount before deducting
  auto deduct_result = update<Account>("balance"_c.set("balance"_c - amount))
                     | where("account_id"_c == from_account_id && "balance"_c >= amount);

  auto after_deduct = deduct_result(transaction);
  if (!after_deduct) {
    // Rollback happens automatically when transaction goes out of scope
    return false;
  }

  // Update receiver's account: add amount
  auto add_result = update<Account>("balance"_c.set("balance"_c + amount))
                  | where("account_id"_c == to_account_id);

  auto after_add = add_result(after_deduct);
  if (!after_add) {
    // Rollback happens automatically when transaction goes out of scope
    return false;
  }

  // Commit the transaction
  auto commit_result = commit(after_add);
  if (!commit_result) {
    return false;
  }

  return true;
}

}  // namespace transaction_transfer_funds

