102	
103	  template <class T>
104	  friend auto operator==(const Col&, const T& _t) {
105	    return transpilation::make_condition(transpilation::conditions::equal(
106	        transpilation::Col<_name, _alias>{},
107	        transpilation::to_transpilation_type(_t)));
108	  }
