110	  template <class T>
111	  friend auto operator!=(const Col&, const T& _t) {
112	    return transpilation::make_condition(transpilation::conditions::not_equal(
113	        transpilation::Col<_name, _alias>{},
114	        transpilation::to_transpilation_type(_t)));
115	  }
116	
117	  template <class T>
118	  friend auto operator<(const Col&, const T& _t) {
119	    return transpilation::make_condition(transpilation::conditions::lesser_than(
120	        transpilation::Col<_name, _alias>{},
121	        transpilation::to_transpilation_type(_t)));
122	  }
123	
124	  template <class T>
125	  friend auto operator<=(const Col&, const T& _t) {
126	    return transpilation::make_condition(
127	        transpilation::conditions::lesser_equal(
128	            transpilation::Col<_name, _alias>{},
129	            transpilation::to_transpilation_type(_t)));
130	  }
131	
132	  template <class T>
133	  friend auto operator>(const Col&, const T& _t) {
134	    return transpilation::make_condition(
135	        transpilation::conditions::greater_than(
136	            transpilation::Col<_name, _alias>{},
137	            transpilation::to_transpilation_type(_t)));
138	  }
139	
140	  template <class T>
141	  friend auto operator>=(const Col&, const T& _t) {
142	    return transpilation::make_condition(
143	        transpilation::conditions::greater_equal(
144	            transpilation::Col<_name, _alias>{},
145	            transpilation::to_transpilation_type(_t)));
146	  }
147	
148	  template <class T>
149	  friend auto operator/(const Col&, const T& _op2) noexcept {
150	    using OtherType = typename transpilation::ToTranspilationType<
151	        std::remove_cvref_t<T>>::Type;
152	
153	    return transpilation::Operation<transpilation::Operator::divides,
154	                                    transpilation::Col<_name, _alias>,
155	                                    OtherType>{
156	        .operand1 = transpilation::Col<_name, _alias>{},
157	        .operand2 = transpilation::to_transpilation_type(_op2)};
158	  }
159	
160	  template <class T>
161	  friend auto operator-(const Col& _op1, const T& _op2) noexcept {
162	    if constexpr (transpilation::is_duration_v<T>) {
163	      using DurationType = std::remove_cvref_t<T>;
164	      return _op1 + DurationType(_op2.count() * (-1));
165	
166	    } else {
167	      using OtherType = typename transpilation::ToTranspilationType<
168	          std::remove_cvref_t<T>>::Type;
169	
170	      return transpilation::Operation<transpilation::Operator::minus,
171	                                      transpilation::Col<_name, _alias>,
172	                                      OtherType>{
173	          .operand1 = transpilation::Col<_name, _alias>{},
174	          .operand2 = transpilation::to_transpilation_type(_op2)};
175	    }
176	  }
177	
178	  template <class T>
179	  friend auto operator%(const Col&, const T& _op2) noexcept {
180	    using OtherType = typename transpilation::ToTranspilationType<
181	        std::remove_cvref_t<T>>::Type;
182	
183	    return transpilation::Operation<transpilation::Operator::mod,
184	                                    transpilation::Col<_name, _alias>,
185	                                    OtherType>{
186	        .operand1 = transpilation::Col<_name, _alias>{},
187	        .operand2 = transpilation::to_transpilation_type(_op2)};
188	  }
189	
190	  template <class T>
191	  friend auto operator*(const Col&, const T& _op2) noexcept {
192	    using OtherType = typename transpilation::ToTranspilationType<
193	        std::remove_cvref_t<T>>::Type;
194	
195	    return transpilation::Operation<transpilation::Operator::multiplies,
196	                                    transpilation::Col<_name, _alias>,
197	                                    OtherType>{
198	        .operand1 = transpilation::Col<_name, _alias>{},
199	        .operand2 = transpilation::to_transpilation_type(_op2)};
200	  }
201	
202	  template <class T>
203	  friend auto operator+(const Col&, const T& _op2) noexcept {
204	    if constexpr (transpilation::is_duration_v<T>) {
205	      using DurationType = std::remove_cvref_t<T>;
206	      return transpilation::Operation<
207	          transpilation::Operator::date_plus_duration,
208	          transpilation::Col<_name, _alias>, rfl::Tuple<DurationType>>{
209	          .operand1 = transpilation::Col<_name, _alias>{},
210	          .operand2 = rfl::Tuple<DurationType>(_op2)};
211	
212	    } else {
213	      using OtherType = typename transpilation::ToTranspilationType<
214	          std::remove_cvref_t<T>>::Type;
215	
216	      return transpilation::Operation<transpilation::Operator::plus,
217	                                      transpilation::Col<_name, _alias>,
218	                                      OtherType>{
219	          .operand1 = transpilation::Col<_name, _alias>{},
220	          .operand2 = transpilation::to_transpilation_type(_op2)};
221	    }
222	  }
223	};
