14	Result<Nothing> Connection::actual_insert(
15	    const std::vector<std::vector<std::optional<std::string>>>& _data,
16	    sqlite3_stmt* _stmt) const noexcept {
17	  for (const auto& row : _data) {
18	    const auto num_cols = static_cast<int>(row.size());
19	
20	    for (int i = 0; i < num_cols; ++i) {
21	      if (row[i]) {
22	        const auto res =
23	            sqlite3_bind_text(_stmt, i + 1, row[i]->c_str(),
24	                              static_cast<int>(row[i]->size()), SQLITE_STATIC);
25	        if (res != SQLITE_OK) {
26	          return error(sqlite3_errmsg(conn_.get()));
27	        }
28	      } else {
29	        const auto res = sqlite3_bind_null(_stmt, i + 1);
30	        if (res != SQLITE_OK) {
31	          return error(sqlite3_errmsg(conn_.get()));
32	        }
33	      }
34	    }
35	
36	    auto res = sqlite3_step(_stmt);
37	    if (res != SQLITE_OK && res != SQLITE_ROW && res != SQLITE_DONE) {
38	      return error(sqlite3_errmsg(conn_.get()));
39	    }
40	
41	    res = sqlite3_reset(_stmt);
42	    if (res != SQLITE_OK) {
43	      return error(sqlite3_errmsg(conn_.get()));
44	    }
45	  }
46	
47	  const auto res = sqlite3_clear_bindings(_stmt);
48	  if (res != SQLITE_OK) {
49	    return error(sqlite3_errmsg(conn_.get()));
50	  }
51	
52	  return Nothing{};
53	}
