81	Result<Nothing> Connection::insert_impl(
82	    const dynamic::Insert& _stmt,
83	    const std::vector<std::vector<std::optional<std::string>>>&
84	        _data) noexcept {
85	  const auto sql = to_sql_impl(_stmt);
86	  return prepare_statement(sql).and_then(
87	      [&](auto _p_stmt) { return actual_insert(_data, _p_stmt.get()); });
88	}
