  std::optional<std::string> avatar_url;
};

bool upsert_user_profile(const UserProfile& u) {
  // Connect to the SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");

  // Check if connection was successful
  if (!conn_result) {
    return false;
  }

  auto conn = conn_result.value();

  // Use insert_or_replace to perform the upsert operation
  // This will insert if the user_id doesn't exist, or replace if it does
  auto result = sqlgen::insert_or_replace(conn, u);

  // Return true if the operation succeeded, false otherwise
  return result.has_value();
}

} // namespace upsert_user_profile
```

**Explanation:**

1. **Connection**: Uses `sqlgen::sqlite::connect("test_db.sqlite")` to connect to the SQLite database. This returns a `Result<Ref<Connection>>`.

2. **Error Handling**: Checks if the connection was successful using `if (!conn_result)`. If it fails, returns `false`.

3. **Upsert Operation**: Uses `sqlgen::insert_or_replace(conn, u)` which implements the SQLite `INSERT OR REPLACE` functionality. This is perfect for upsert operations:
   - If a record with the same `user_id` (PRIMARY KEY) exists, it will be replaced with the new `bio` and `avatar_url`
   - If no record exists, it will insert a new one

4. **Return Value**: Returns `true` if the operation succeeded (i.e., `result.has_value()` is true), otherwise `false`.

The `insert_or_replace` function in `sqlgen` automatically:
- Detects that `UserProfile` has a primary key constraint (`sqlgen::PrimaryKey<int> user_id`)
- Generates the appropriate `INSERT OR REPLACE INTO UserProfile (user_id, bio, avatar_url) VALUES (?, ?, ?)` SQL statement
- Executes it with the provided data

This implementation is clean, idiomatic for the `sqlgen` library, and handles both insert and update cases automatically through SQLite's `INSERT OR REPLACE` semantics.

