namespace schema_create_view_sales_summary {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
  int stock;
};

struct Sale {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct SalesSummary {
  static constexpr bool is_view = true;
  std::string product_name;
  int total_quantity;
  double total_revenue;
};

/**
 * Function: Create a view SalesSummary that aggregates sales by product.
 *
 * @return true if view creation succeeds, false otherwise
 */
bool create_view_sales_summary() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Build the SELECT query with JOIN, aggregations, and GROUP BY
  // SELECT p.name as product_name, SUM(s.quantity) as total_quantity, SUM(s.amount) as total_revenue
  // FROM Sale s
  // JOIN Product p ON s.product_id = p.product_id
  // GROUP BY p.name
  const auto sales_query =
      select_from<Sale, "s">(
          "name"_t1 | as<"product_name">,
          sum("quantity"_s) | as<"total_quantity">,
          sum("amount"_s) | as<"total_revenue">) |
      inner_join<Product, "t1">("product_id"_s == "product_id"_t1) |
      group_by("name"_t1);

  // Create the view from the query
  const auto create_view = create_as<SalesSummary>(sales_query) | if_not_exists;

  // Connect to the database and execute the view creation
  auto result = sqlite::connect("test_db.sqlite")
                    .and_then(create_view);

  return result.has_value();
}

}  // namespace schema_create_view_sales_summary

