```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace right_join_departments_projects {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string name;
};

struct Project {
  sqlgen::PrimaryKey<int> project_id;
  int department_id;
  std::string name;
};

struct DepProj {
  std::optional<std::string> department_name;
  std::string project_name;
};

/**
 * description: right_join_departments_projects.
 * This function demonstrates how to perform a right join between departments and projects using sqlgen read API.
 * It returns a vector of DepProj structs, where each struct contains the department name (if available) and the project name.
 * Returns: std::vector<DepProj>.
 */
std::vector<DepProj> right_join_departments_projects() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Build the query: SELECT from Department (t1), RIGHT JOIN with Project (t2)
  // This will include all projects, even those without a matching department
  const auto query =
      select_from<Department, "t1">("name"_t1 | as<"department_name">,
                                    "name"_t2 | as<"project_name">) |
      right_join<Project, "t2">("department_id"_t1 == "department_id"_t2) |
      to<std::vector<DepProj>>;

  // Connect to the database and execute the query
  const auto result = sqlite::connect("test_db.sqlite")
                          .and_then(query)
                          .value();

  return result;
}

}  // namespace right_join_departments_projects
```

## Explanation:

1. **Using directives**: I'm using the `sqlgen` and `sqlgen::literals` namespaces to access the library's functionality and column literal operators.

2. **Query construction**: 
   - `select_from<Department, "t1">` starts the query from the Department table with alias "t1"
   - The first parameter selects `name` from Department (t1) aliased as "department_name"
   - The second parameter selects `name` from Project (t2) aliased as "project_name"

3. **RIGHT JOIN**: 
   - `right_join<Project, "t2">` performs a RIGHT JOIN with the Project table (alias "t2")
   - The join condition is `"department_id"_t1 == "department_id"_t2`, matching the department_id columns
   - The `_t1` and `_t2` suffixes are user-defined literals that reference columns from the aliased tables

4. **Result conversion**: 
   - `to<std::vector<DepProj>>` converts the query results to the target type

5. **Execution**:
   - `sqlite::connect("test_db.sqlite")` connects to the database file
   - `.and_then(query)` executes the query (using monadic error handling)
   - `.value()` extracts the result from the `Result` wrapper

The RIGHT JOIN ensures all projects are included in the results, with `department_name` being `std::nullopt` for projects that don't have a matching department.

