  // This will include all projects, even those without a matching department
  const auto query =
      select_from<Department, "t1">("name"_t1 | as<"department_name">,
                                    "name"_t2 | as<"project_name">) |
      right_join<Project, "t2">("department_id"_t1 == "department_id"_t2) |
