1	#ifndef SQLGEN_COL_HPP_
2	#define SQLGEN_COL_HPP_
3	
4	#include <chrono>
5	#include <rfl.hpp>
6	#include <string>
7	
8	#include "transpilation/As.hpp"
9	#include "transpilation/Col.hpp"
10	#include "transpilation/Condition.hpp"
11	#include "transpilation/Desc.hpp"
12	#include "transpilation/Operation.hpp"
13	#include "transpilation/Operator.hpp"
14	#include "transpilation/Set.hpp"
15	#include "transpilation/Value.hpp"
16	#include "transpilation/conditions.hpp"
17	#include "transpilation/is_duration.hpp"
18	#include "transpilation/to_transpilation_type.hpp"
19	
20	namespace sqlgen {
21	
22	template <rfl::internal::StringLiteral _name,
23	          rfl::internal::StringLiteral _alias = "">
24	struct Col {
25	  using ColType = transpilation::Col<_name, _alias>;
26	  using Name = rfl::Literal<_name>;
27	  using Alias = rfl::Literal<_alias>;
28	
29	  template <rfl::internal::StringLiteral _new_name>
30	  auto as() const noexcept {
31	    return transpilation::As<transpilation::Col<_name, _alias>, _new_name>{
32	        .val = transpilation::Col<_name, _alias>{}};
33	  }
34	
35	  /// Signals to order_by that this column is to be sorted in descending order.
36	  auto desc() const noexcept {
37	    return transpilation::Desc<transpilation::Col<_name, _alias>>{};
38	  }
39	
40	  /// Returns the column name.
41	  std::string name() const noexcept { return Name().str(); }
42	
43	  /// Returns an IN condition.
44	  template <class... Ts>
45	  auto in(const Ts&... _ts) const noexcept {
46	    return transpilation::make_condition(transpilation::conditions::in(
47	        transpilation::Col<_name, _alias>{}, _ts...));
48	  }
49	
50	  /// Returns an IS NULL condition.
51	  auto is_null() const noexcept {
52	    return transpilation::make_condition(transpilation::conditions::is_null(
53	        transpilation::Col<_name, _alias>{}));
54	  }
55	
56	  /// Returns a IS NOT NULL condition.
57	  auto is_not_null() const noexcept {
58	    return transpilation::make_condition(transpilation::conditions::is_not_null(
59	        transpilation::Col<_name, _alias>{}));
60	  }
61	
62	  /// Returns a LIKE condition.
63	  auto like(const std::string& _pattern) const noexcept {
64	    return transpilation::make_condition(transpilation::conditions::like(
65	        transpilation::Col<_name, _alias>{}, _pattern));
66	  }
67	
68	  /// Returns a NOT LIKE condition.
69	  auto not_like(const std::string& _pattern) const noexcept {
70	    return transpilation::make_condition(transpilation::conditions::not_like(
71	        transpilation::Col<_name, _alias>{}, _pattern));
72	  }
73	
74	  /// Returns a NOT IN condition.
75	  template <class... Ts>
76	  auto not_in(const Ts&... _ts) const noexcept {
77	    return transpilation::make_condition(transpilation::conditions::not_in(
78	        transpilation::Col<_name, _alias>{}, _ts...));
79	  }
80	
81	  /// Returns a SET clause in an UPDATE statement.
82	  template <class T>
83	  auto set(const T& _to) const noexcept {
84	    return transpilation::Set<transpilation::Col<_name, _alias>,
85	                              std::remove_cvref_t<T>>{.to = _to};
86	  }
87	
88	  /// Returns a SET clause in an UPDATE statement.
89	  template <rfl::internal::StringLiteral _other_name,
90	            rfl::internal::StringLiteral _other_alias>
91	  auto set(const Col<_other_name, _other_alias>& _to) const noexcept {
92	    return transpilation::Set<transpilation::Col<_name, _alias>,
93	                              transpilation::Col<_other_name, _other_alias>>{
94	        .to = transpilation::Col<_other_name, _other_alias>{}};
95	  }
96	
97	  /// Returns a SET clause in an UPDATE statement.
98	  auto set(const char* _to) const noexcept {
99	    return transpilation::Set<transpilation::Col<_name, _alias>, std::string>{
100	        .to = _to};

1	#ifndef SQLGEN_READ_HPP_
2	#define SQLGEN_READ_HPP_
3	
4	#include <ranges>
5	#include <type_traits>
6	
7	#include "Ref.hpp"
8	#include "Result.hpp"
9	#include "internal/is_range.hpp"
10	#include "is_connection.hpp"
11	#include "limit.hpp"
12	#include "order_by.hpp"
13	#include "transpilation/order_by_t.hpp"
14	#include "transpilation/read_to_select_from.hpp"
15	#include "transpilation/value_t.hpp"
16	#include "where.hpp"
17	
18	namespace sqlgen {
19	
20	template <class ContainerType, class WhereType, class OrderByType,
21	          class LimitType, class Connection>
22	  requires is_connection<Connection>
23	auto read_impl(const Ref<Connection>& _conn, const WhereType& _where,
24	               const LimitType& _limit) {
25	  using ValueType = transpilation::value_t<ContainerType>;
26	  const auto query =
27	      transpilation::read_to_select_from<ValueType, WhereType, OrderByType,
28	                                         LimitType>(_where, _limit);
29	  return _conn->template read<ContainerType>(query);
30	}
31	
32	template <class ContainerType, class WhereType, class OrderByType,
33	          class LimitType, class Connection>
34	  requires is_connection<Connection>
35	auto read_impl(const Result<Ref<Connection>>& _res, const WhereType& _where,
36	               const LimitType& _limit) {
37	  return _res.and_then([&](const auto& _conn) {
38	    return read_impl<ContainerType, WhereType, OrderByType, LimitType>(
39	        _conn, _where, _limit);
40	  });
41	}
42	
43	template <class Type, class WhereType = Nothing, class OrderByType = Nothing,
44	          class LimitType = Nothing>
45	struct Read {
46	  auto operator()(const auto& _conn) const {
47	    if constexpr (std::ranges::input_range<std::remove_cvref_t<Type>> ||
48	                  internal::is_range_v<Type>) {
49	      return read_impl<Type, WhereType, OrderByType, LimitType>(_conn, where_,
50	                                                                limit_);
51	
52	    } else {
53	      return read_impl<std::vector<Type>, WhereType, OrderByType, LimitType>(
54	                 _conn, where_, limit_)
55	          .and_then([](auto&& _vec) -> Result<Type> {
56	            if (_vec.size() != 1) {
57	              return error(
58	                  "Because the provided type was not a container, the query "
59	                  "needs to return exactly one result, but it did return " +
60	                  std::to_string(_vec.size()) + " results.");
61	            }
62	            return std::move(_vec[0]);
63	          });
64	    }
65	  }
66	
67	  template <class ConditionType>
68	  friend auto operator|(const Read& _r, const Where<ConditionType>& _where) {
69	    static_assert(std::is_same_v<WhereType, Nothing>,
70	                  "You cannot call where(...) twice (but you can apply more "
71	                  "than one condition by combining them with && or ||).");
72	    static_assert(std::is_same_v<OrderByType, Nothing>,
73	                  "You cannot call order_by(...) before where(...).");
74	    static_assert(std::is_same_v<LimitType, Nothing>,
75	                  "You cannot call limit(...) before where(...).");
76	    return Read<Type, ConditionType, OrderByType, LimitType>{
77	        .where_ = _where.condition};
78	  }
79	
80	  template <class... ColTypes>
81	  friend auto operator|(const Read& _r, const OrderBy<ColTypes...>&) {
82	    static_assert(
83	        std::is_same_v<OrderByType, Nothing>,
84	        "You cannot call order_by(...) twice (but you can order by more "
