      left_join<Friendship, "f">("user_id"_t1 == "user1_id"_t2) |
      group_by("user_id"_t1, "username"_t1) |
      order_by(count("user2_id"_t2).desc()) |
      to<std::vector<PopularUser>>;

  auto popular_users = conn.and_then(popular_users_query).value_or(std::vector<PopularUser>{});

  // Main query: Return all friend connections
  const auto friend_connections_query =
