22	namespace sqlgen {
23	
24	template <class ItBegin, class ItEnd, class Connection>
25	  requires is_connection<Connection>
26	Result<Ref<Connection>> write(const Ref<Connection>& _conn, ItBegin _begin,
27	                              ItEnd _end) noexcept {
28	  using T =
29	      std::remove_cvref_t<typename std::iterator_traits<ItBegin>::value_type>;
30	
31	  const auto start_write = [&](const auto&) -> Result<Nothing> {
32	    const auto write_stmt =
33	        transpilation::to_insert_or_write<T, dynamic::Write>();
34	    return _conn->start_write(write_stmt);
35	  };
36	
37	  const auto write = [&](const auto&) -> Result<Nothing> {
38	    const auto res = _conn->write(_begin, _end);
39	    if (!res) {
40	      _conn->end_write();
41	    }
42	    return res;
43	  };
44	
45	  const auto end_write = [&](const auto&) -> Result<Nothing> {
46	    return _conn->end_write();
47	  };
48	
49	  const auto create_table_stmt = transpilation::to_create_table<T>();
50	
51	  return _conn->execute(_conn->to_sql(create_table_stmt))
52	      .and_then(start_write)
53	      .and_then(write)
54	      .and_then(end_write)
55	      .transform([&](const auto&) { return _conn; });
56	}
57	
58	template <class ItBegin, class ItEnd, class Connection>
59	  requires is_connection<Connection>
60	Result<Ref<Connection>> write(const Result<Ref<Connection>>& _res,
61	                              ItBegin _begin, ItEnd _end) noexcept {
62	  return _res.and_then(
63	      [&](const auto& _conn) { return write(_conn, _begin, _end); });
64	}
65	
66	template <class ContainerType>
67	auto write(const auto& _conn, const ContainerType& _container) noexcept {
68	  if constexpr (std::ranges::input_range<std::remove_cvref_t<ContainerType>>) {
69	    return write(_conn, _container.begin(), _container.end());
70	  } else {
71	    return write(_conn, &_container, &_container + 1);
72	  }
73	}
74	
75	template <class ContainerType>
76	auto write(const auto& _conn,
77	           const std::reference_wrapper<ContainerType>& _data) {
78	  return write(_conn, _data.get());
79	}
80	
81	template <class ContainerType>
82	struct Write {
83	  auto operator()(const auto& _conn) const { return write(_conn, data_); }
84	
85	  ContainerType data_;
86	};
87	
88	template <class ContainerType>
89	Write<ContainerType> write(const ContainerType& _data) {
90	  return Write<ContainerType>{.data_ = _data};
91	}
