#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace analyze_social_network {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct Friendship {
  int user1_id;
  int user2_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct FriendConnection {
  std::string user1_name;
  std::string user2_name;
};

/**
 * Analyze social network data by creating temporary SQL tables for User and Friendship.
 * Returns: std::vector<FriendConnection>.
 */
std::vector<FriendConnection> analyze_social_network_impl(const std::vector<User>& users, const std::vector<Friendship>& friendships) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database and populate tables
  auto conn_result = sqlite::connect("test_db.sqlite")
                         .and_then(write(std::ref(users)))
                         .and_then(write(std::ref(friendships)));

  if (!conn_result) {
    return std::vector<FriendConnection>{};
  }

  auto conn = conn_result.value();

  // Query 1: Find mutual friends using SELF-JOIN
  // Find pairs of users who are friends and count their mutual friends
  struct MutualFriendResult {
    std::string user1_name;
    std::string user2_name;
    int mutual_count;
  };

  const auto mutual_friends_query =
      select_from<User, "u1">(
          "username"_t1 | as<"user1_name">,
          "username"_t4 | as<"user2_name">,
          count() | as<"mutual_count">) |
      inner_join<Friendship, "f1">("user_id"_t1 == "user1_id"_t2) |
      inner_join<Friendship, "f2">("user2_id"_t2 == "user1_id"_t3) |
      inner_join<User, "u2">("user2_id"_t3 == "user_id"_t4) |
      where("user_id"_t1 < "user_id"_t4) |
      group_by("user_id"_t1, "user_id"_t4) |
      to<std::vector<MutualFriendResult>>;

  auto mutual_friends = conn.and_then(mutual_friends_query).value_or(std::vector<MutualFriendResult>{});

  // Query 2: Find users with friend count using LEFT JOIN and aggregation
  struct UserFriendCount {
    int user_id;
    std::string username;
    int friend_count;
  };

  const auto user_friend_counts =
      select_from<User, "u">(
          "user_id"_t1 | as<"user_id">,
          "username"_t1 | as<"username">,
          count("user1_id"_t2) | as<"friend_count">) |
      left_join<Friendship, "f">("user_id"_t1 == "user1_id"_t2) |
      group_by("user_id"_t1, "username"_t1) |
      order_by("friend_count"_t2.desc()) |
      to<std::vector<UserFriendCount>>;

  auto friend_counts = conn.and_then(user_friend_counts).value_or(std::vector<UserFriendCount>{});

  // Query 3: Find friend-of-friend relationships
  // People connected through exactly one mutual friend
  struct FriendOfFriend {
    std::string user_name;
    std::string fof_name;
    std::string mutual_friend_name;
  };

  const auto fof_query =
      select_from<User, "u1">(
          "username"_t1 | as<"user_name">,
          "username"_t5 | as<"fof_name">,
          "username"_t3 | as<"mutual_friend_name">) |
      inner_join<Friendship, "f1">("user_id"_t1 == "user1_id"_t2) |
      inner_join<User, "u2">("user2_id"_t2 == "user_id"_t3) |
      inner_join<Friendship, "f2">("user_id"_t3 == "user1_id"_t4) |
      inner_join<User, "u3">("user2_id"_t4 == "user_id"_t5) |
      where("user_id"_t1 != "user_id"_t5) |
      to<std::vector<FriendOfFriend>>;

  auto fof_results = conn.and_then(fof_query).value_or(std::vector<FriendOfFriend>{});

  // Query 4: Count friends per user and identify most connected users
  struct PopularUser {
    std::string username;
    int friend_count;
  };

  const auto popular_users_query =
      select_from<User, "u">(
          "username"_t1 | as<"username">,
          count("user2_id"_t2) | as<"friend_count">) |
      left_join<Friendship, "f">("user_id"_t1 == "user1_id"_t2) |
      group_by("user_id"_t1, "username"_t1) |
      order_by(count("user2_id"_t2).desc()) |
      to<std::vector<PopularUser>>;

  auto popular_users = conn.and_then(popular_users_query).value_or(std::vector<PopularUser>{});

  // Main query: Return all friend connections
  const auto friend_connections_query =
      select_from<User, "u1">(
          "username"_t1 | as<"user1_name">,
