friend auto operator|(const SelectFrom& _s, const GroupBy<ColTypes...>&) {
  static_assert(
      std::is_same_v<GroupByType, Nothing>,
      "You cannot call group_by(...) twice (but you can group by more "
      "than one column).");
  static_assert(std::is_same_v<OrderByType, Nothing>,
