```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace calculate_order_metrics {

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  std::optional<double> discount_rate;
  std::optional<double> tax_rate;
};

struct OrderMetrics {
  int item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  double discount_rate;
  double tax_rate;
  double gross_total;
  double discounted_total;
  double final_total;
  double unit_cost;
  int quantity_group;
  double estimated_profit;
};

/**
 * Calculate per-item order metrics by loading the provided items into a temporary SQLite table
 * and evaluating SQL expressions for totals, discounts, taxes, cost, grouping, and estimated profit.
 * @param items Vector of OrderItem records to analyze.
 * @return std::vector<OrderMetrics> Analysis results for each order item.
 */
std::vector<OrderMetrics> calculate_order_metrics_impl(const std::vector<OrderItem>& items) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to in-memory SQLite database
  auto conn = sqlite::connect();

  // Write items to the database (creates table and inserts data)
  auto result = write(conn, items);

  // Build the query with all calculated metrics
  auto query = select_from<OrderItem>(
      "item_id"_c,
      "order_id"_c,
      "product_id"_c,
      "unit_price"_c,
      "quantity"_c,
      coalesce("discount_rate"_c, 0.0) | as<"discount_rate">,
      coalesce("tax_rate"_c, 0.0) | as<"tax_rate">,
      ("unit_price"_c * "quantity"_c) | as<"gross_total">,
      (("unit_price"_c * "quantity"_c) * (1.0 - coalesce("discount_rate"_c, 0.0) / 100.0)) | as<"discounted_total">,
      ((("unit_price"_c * "quantity"_c) * (1.0 - coalesce("discount_rate"_c, 0.0) / 100.0)) * (1.0 + coalesce("tax_rate"_c, 0.0) / 100.0)) | as<"final_total">,
      (("unit_price"_c * "quantity"_c) / "quantity"_c) | as<"unit_cost">,
      ("quantity"_c % 10) | as<"quantity_group">,
      ("unit_price"_c * 0.3) | as<"estimated_profit">
  ) | to<std::vector<OrderMetrics>>;

  // Execute the query and return results
  auto metrics = result.and_then(query).value();

  return metrics;
}

}  // namespace calculate_order_metrics
```

## Explanation

The implementation uses the `sqlgen` library to:

1. **Connect to SQLite**: Uses `sqlite::connect()` to create an in-memory database connection
2. **Write data**: Uses `write(conn, items)` to create the `OrderItem` table and insert all items
3. **Build complex query**: Uses `select_from<OrderItem>()` with column expressions to:
   - Select base fields: `item_id`, `order_id`, `product_id`, `unit_price`, `quantity`
   - Handle nullable fields with `coalesce()` to provide default values (0.0 for NULL)
   - Perform arithmetic operations:
     - **Multiplication**: `unit_price * quantity` for gross total
     - **Division**: `total / quantity` for unit cost
     - **Modulo**: `quantity % 10` for grouping
     - **Addition/Subtraction**: Complex nested expressions for discounts and taxes
   - Use the pipe operator `|` with `as<"name">` to alias calculated columns
4. **Execute query**: Chain operations with `and_then()` and extract value with `.value()`

The key features demonstrated:
- Column literals using `"column_name"_c` syntax
- Arithmetic operators: `*`, `/`, `%`, `+`, `-`
- The `coalesce()` function for NULL handling (equivalent to SQL's COALESCE)
- The pipe operator `|` for chaining operations
- The `as<"alias">` for column aliasing
- The `to<std::vector<T>>` for specifying the result type
- Monadic chaining with `and_then()` and `value()` for error handling

