Customer read_single_record_by_id(int id) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Read the single record by id using where clause
  // The read<Customer> returns a single Customer object (not a vector)
  // when used with a where condition that matches exactly one record
  const auto customer = (sqlgen::read<Customer> | where("customer_id"_c == id))(conn).value();

  return customer;
}

}  // namespace read_single_record_by_id
