8	namespace sqlgen {
9	
10	template <rfl::internal::StringLiteral _alias, transpilation::JoinType _how,
11	          class TableOrQueryType, class ConditionType>
12	auto join(const TableOrQueryType& _table_or_query, const ConditionType& _on) {
13	  return transpilation::Join<TableOrQueryType, ConditionType, _alias, _how>{
14	      .table_or_query = _table_or_query, .on = _on};
15	};
16	
17	template <rfl::internal::StringLiteral _alias, class QueryType,
18	          class ConditionType>
19	auto full_join(const QueryType& _query, const ConditionType& _on) {
20	  return join<_alias, transpilation::JoinType::full_join>(_query, _on);
21	}
22	
23	template <class TableType, rfl::internal::StringLiteral _alias,
24	          class ConditionType>
25	auto full_join(const ConditionType& _on) {
26	  return join<_alias, transpilation::JoinType::full_join>(
27	      transpilation::TableWrapper<TableType>{}, _on);
28	}
29	
30	template <rfl::internal::StringLiteral _alias, class QueryType,
31	          class ConditionType>
32	auto inner_join(const QueryType& _query, const ConditionType& _on) {
33	  return join<_alias, transpilation::JoinType::inner_join>(_query, _on);
34	}
35	
36	template <class TableType, rfl::internal::StringLiteral _alias,
37	          class ConditionType>
38	auto inner_join(const ConditionType& _on) {
39	  return join<_alias, transpilation::JoinType::inner_join>(
40	      transpilation::TableWrapper<TableType>{}, _on);
41	}
42	
43	template <rfl::internal::StringLiteral _alias, class QueryType,
44	          class ConditionType>
45	auto left_join(const QueryType& _query, const ConditionType& _on) {
46	  return join<_alias, transpilation::JoinType::left_join>(_query, _on);
47	}
48	
49	template <class TableType, rfl::internal::StringLiteral _alias,
50	          class ConditionType>
51	auto left_join(const ConditionType& _on) {
52	  return join<_alias, transpilation::JoinType::left_join>(
53	      transpilation::TableWrapper<TableType>{}, _on);
54	}
55	
56	template <rfl::internal::StringLiteral _alias, class QueryType,
57	          class ConditionType>
58	auto right_join(const QueryType& _query, const ConditionType& _on) {
59	  return join<_alias, transpilation::JoinType::right_join>(_query, _on);
