1	#include <gtest/gtest.h>
2	
3	#include <rfl.hpp>
4	#include <rfl/json.hpp>
5	#include <sqlgen.hpp>
6	#include <sqlgen/sqlite.hpp>
7	#include <vector>
8	
9	namespace test_joins_two_tables {
10	
11	struct Person {
12	  sqlgen::PrimaryKey<uint32_t> id;
13	  std::string first_name;
14	  std::string last_name;
15	  double age;
16	};
17	
18	struct Relationship {
19	  uint32_t parent_id;
20	  uint32_t child_id;
21	};
22	
23	TEST(sqlite, test_joins_two_tables) {
24	  const auto people1 = std::vector<Person>(
25	      {Person{
26	           .id = 0, .first_name = "Homer", .last_name = "Simpson", .age = 45},
27	       Person{
28	           .id = 1, .first_name = "Marge", .last_name = "Simpson", .age = 40},
29	       Person{.id = 2, .first_name = "Bart", .last_name = "Simpson", .age = 10},
30	       Person{.id = 3, .first_name = "Lisa", .last_name = "Simpson", .age = 8},
31	       Person{
32	           .id = 4, .first_name = "Maggie", .last_name = "Simpson", .age = 0}});
33	
34	  const auto relationships =
35	      std::vector<Relationship>({Relationship{.parent_id = 0, .child_id = 2},
36	                                 Relationship{.parent_id = 0, .child_id = 3},
37	                                 Relationship{.parent_id = 0, .child_id = 4},
38	                                 Relationship{.parent_id = 1, .child_id = 2},
39	                                 Relationship{.parent_id = 1, .child_id = 3},
40	                                 Relationship{.parent_id = 1, .child_id = 4}});
41	
42	  using namespace sqlgen;
43	  using namespace sqlgen::literals;
44	
45	  struct ParentAndChild {
46	    std::string last_name;
47	    std::string first_name_parent;
48	    std::string first_name_child;
49	    double parent_age_at_birth;
50	  };
51	
52	  const auto get_people =
53	      select_from<Person, "t1">(
54	          "last_name"_t1 | as<"last_name">,
55	          "first_name"_t1 | as<"first_name_parent">,
56	          "first_name"_t3 | as<"first_name_child">,
57	          ("age"_t1 - "age"_t3) | as<"parent_age_at_birth">) |
58	      inner_join<Relationship, "t2">("id"_t1 == "parent_id"_t2) |
59	      inner_join<Person, "t3">("id"_t3 == "child_id"_t2) |
60	      order_by("id"_t1, "id"_t3) | to<std::vector<ParentAndChild>>;
61	
62	  const auto people = sqlite::connect()
63	                          .and_then(write(std::ref(people1)))
64	                          .and_then(write(std::ref(relationships)))
65	                          .and_then(get_people)
66	                          .value();
67	
68	  const std::string expected_query =
69	      R"(SELECT t1."last_name" AS "last_name", t1."first_name" AS "first_name_parent", t3."first_name" AS "first_name_child", (t1."age") - (t3."age") AS "parent_age_at_birth" FROM "Person" t1 INNER JOIN "Relationship" t2 ON t1."id" = t2."parent_id" INNER JOIN "Person" t3 ON t3."id" = t2."child_id" ORDER BY t1."id", t3."id")";
70	  const std::string expected =
71	      R"([{"last_name":"Simpson","first_name_parent":"Homer","first_name_child":"Bart","parent_age_at_birth":35.0},{"last_name":"Simpson","first_name_parent":"Homer","first_name_child":"Lisa","parent_age_at_birth":37.0},{"last_name":"Simpson","first_name_parent":"Homer","first_name_child":"Maggie","parent_age_at_birth":45.0},{"last_name":"Simpson","first_name_parent":"Marge","first_name_child":"Bart","parent_age_at_birth":30.0},{"last_name":"Simpson","first_name_parent":"Marge","first_name_child":"Lisa","parent_age_at_birth":32.0},{"last_name":"Simpson","first_name_parent":"Marge","first_name_child":"Maggie","parent_age_at_birth":40.0}])";
72	
73	  EXPECT_EQ(sqlite::to_sql(get_people), expected_query);
74	  EXPECT_EQ(rfl::json::write(people), expected);
75	}
76	
77	}  // namespace test_joins_two_tables
