1	#ifndef SQLGEN_READ_HPP_
2	#define SQLGEN_READ_HPP_
3	
4	#include <ranges>
5	#include <type_traits>
6	
7	#include "Ref.hpp"
8	#include "Result.hpp"
9	#include "internal/is_range.hpp"
10	#include "is_connection.hpp"
11	#include "limit.hpp"
12	#include "order_by.hpp"
13	#include "transpilation/order_by_t.hpp"
14	#include "transpilation/read_to_select_from.hpp"
15	#include "transpilation/value_t.hpp"
16	#include "where.hpp"
17	
18	namespace sqlgen {
19	
20	template <class ContainerType, class WhereType, class OrderByType,
21	          class LimitType, class Connection>
22	  requires is_connection<Connection>
23	auto read_impl(const Ref<Connection>& _conn, const WhereType& _where,
24	               const LimitType& _limit) {
25	  using ValueType = transpilation::value_t<ContainerType>;
26	  const auto query =
27	      transpilation::read_to_select_from<ValueType, WhereType, OrderByType,
28	                                         LimitType>(_where, _limit);
29	  return _conn->template read<ContainerType>(query);
30	}
31	
32	template <class ContainerType, class WhereType, class OrderByType,
33	          class LimitType, class Connection>
34	  requires is_connection<Connection>
35	auto read_impl(const Result<Ref<Connection>>& _res, const WhereType& _where,
36	               const LimitType& _limit) {
37	  return _res.and_then([&](const auto& _conn) {
38	    return read_impl<ContainerType, WhereType, OrderByType, LimitType>(
39	        _conn, _where, _limit);
40	  });
41	}
42	
43	template <class Type, class WhereType = Nothing, class OrderByType = Nothing,
44	          class LimitType = Nothing>
45	struct Read {
46	  auto operator()(const auto& _conn) const {
47	    if constexpr (std::ranges::input_range<std::remove_cvref_t<Type>> ||
48	                  internal::is_range_v<Type>) {
49	      return read_impl<Type, WhereType, OrderByType, LimitType>(_conn, where_,
50	                                                                limit_);
51	
52	    } else {
53	      return read_impl<std::vector<Type>, WhereType, OrderByType, LimitType>(
54	                 _conn, where_, limit_)
55	          .and_then([](auto&& _vec) -> Result<Type> {
56	            if (_vec.size() != 1) {
57	              return error(
58	                  "Because the provided type was not a container, the query "
59	                  "needs to return exactly one result, but it did return " +
60	                  std::to_string(_vec.size()) + " results.");
61	            }
62	            return std::move(_vec[0]);
63	          });
64	    }
65	  }
66	
67	  template <class ConditionType>
68	  friend auto operator|(const Read& _r, const Where<ConditionType>& _where) {
69	    static_assert(std::is_same_v<WhereType, Nothing>,
70	                  "You cannot call where(...) twice (but you can apply more "
71	                  "than one condition by combining them with && or ||).");
72	    static_assert(std::is_same_v<OrderByType, Nothing>,
73	                  "You cannot call order_by(...) before where(...).");
74	    static_assert(std::is_same_v<LimitType, Nothing>,
75	                  "You cannot call limit(...) before where(...).");
76	    return Read<Type, ConditionType, OrderByType, LimitType>{
77	        .where_ = _where.condition};
78	  }
79	
80	  template <class... ColTypes>
81	  friend auto operator|(const Read& _r, const OrderBy<ColTypes...>&) {
82	    static_assert(
83	        std::is_same_v<OrderByType, Nothing>,
84	        "You cannot call order_by(...) twice (but you can order by more "
85	        "than one column).");
86	    static_assert(std::is_same_v<LimitType, Nothing>,
87	                  "You cannot call limit(...) before order_by.");
88	    static_assert(sizeof...(ColTypes) != 0,
89	                  "You must assign at least one column to order by(...).");
90	    return Read<Type, WhereType,
91	                transpilation::order_by_t<
92	                    transpilation::value_t<Type>, Nothing,
93	                    typename std::remove_cvref_t<ColTypes>::ColType...>,
94	                LimitType>{.where_ = _r.where_};
95	  }
96	
97	  friend auto operator|(const Read& _r, const Limit& _limit) {
98	    static_assert(std::is_same_v<LimitType, Nothing>,
99	                  "You cannot call limit(...) twice.");
100	    return Read<Type, WhereType, OrderByType, Limit>{.where_ = _r.where_,
101	                                                     .limit_ = _limit};
102	  }
103	
104	  WhereType where_;
105	
106	  LimitType limit_;
107	};
108	
109	template <class ContainerType>
110	const auto read = Read<ContainerType>{};
111	
112	}  // namespace sqlgen
113	
114	#endif
115

