Here's the complete implementation of the `cascade_delete_demo` function:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace cascade_delete_demo {

struct Parent {
  sqlgen::PrimaryKey<int> parent_id;
  std::string name;
};

struct Child {
  sqlgen::PrimaryKey<int> child_id;
  sqlgen::ForeignKey<int, Parent, "parent_id"> parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * Returns: bool.
 */
bool cascade_delete_demo() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn = sqlite::connect("test_db.sqlite");
  if (!conn) {
    return false;
  }

  // Create tables with CASCADE constraint
  auto result = conn
    .and_then(create_table<Parent> | if_not_exists | cascade)
    .and_then(create_table<Child> | if_not_exists | cascade);

  if (!result) {
    return false;
  }

  // Insert parent record
  Parent parent{.parent_id = 1, .name = "Parent 1"};
  result = result.and_then(insert(parent));
  if (!result) {
    return false;
  }

  // Insert child records with same parent_id
  std::vector<Child> children = {
    Child{.child_id = 1, .parent_id = 1, .note = "Child 1"},
    Child{.child_id = 2, .parent_id = 1, .note = "Child 2"},
    Child{.child_id = 3, .parent_id = 1, .note = "Child 3"}
  };

  result = result.and_then(insert(children));
  if (!result) {
    return false;
  }

  // Delete parent record
  auto delete_query = delete_from<Parent> | where("parent_id"_c == 1);
  result = result.and_then(delete_query);
  if (!result) {
    return false;
  }

  // Verify child records are automatically deleted
  auto children_after = result.and_then(read<std::vector<Child>>);
  if (!children_after) {
    return false;
  }

  // If cascade delete worked, children vector should be empty
  return children_after.value().empty();
}

}  // namespace cascade_delete_demo
```

## Key implementation details:

1. **Database connection**: Uses `sqlite::connect("test_db.sqlite")` to connect to the SQLite database
2. **Table creation**: Creates both `Parent` and `Child` tables using `create_table` with `if_not_exists` and `cascade` modifiers
3. **Insert data**: Inserts one parent record and three child records with matching `parent_id = 1`
4. **Delete parent**: Deletes the parent record using `delete_from<Parent>` with a `where` clause
5. **Verify cascade**: Reads all child records and verifies the vector is empty, confirming cascade deletion worked
6. **Return result**: Returns `true` if cascade deletion successfully removed all child records, `false` otherwise

The function uses the sqlgen library's fluent API with the `and_then` pattern for chaining operations and proper error handling through the `Result` type.

