#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace update_set_operations {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
  std::string status;
};

/**
 * description: update_set_operations.
 * This function demonstrates how to use set operations in update statements using sqlgen write API.
 * It returns true if the update operations are successful, and false otherwise.
 * Returns: bool.
 */
bool update_set_operations() {
  try {
    // Connect to the SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");
    if (!conn) {
      return false;
    }

    // Create the Account table
    auto create_result = sqlgen::create_table<Account>{.if_not_exists_ = true}(conn);
    if (!create_result) {
      return false;
    }

    // Insert some initial test data
    std::vector<Account> initial_accounts = {
        Account{.account_id = 1, .balance = 1000.0, .status = "active"},
        Account{.account_id = 2, .balance = 2000.0, .status = "inactive"},
        Account{.account_id = 3, .balance = 1500.0, .status = "active"}
    };

    auto write_result = sqlgen::write(conn, initial_accounts);
    if (!write_result) {
      return false;
    }

    // Use namespace for literals and functions
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Update balance and status using set() operations
    // Set balance to 2500.0 and status to "premium" for account_id = 1
    auto update1 = update<Account>(
        "balance"_c.set(2500.0),
        "status"_c.set("premium")
    ) | where("account_id"_c == 1);

    auto update1_result = update1(conn);
    if (!update1_result) {
      return false;
    }

    // Update balance to 3000.0 for accounts with status "inactive"
    auto update2 = update<Account>(
        "balance"_c.set(3000.0)
    ) | where("status"_c == "inactive");

    auto update2_result = update2(conn);
    if (!update2_result) {
      return false;
    }

    // Update status to "verified" for accounts with balance > 2000
    auto update3 = update<Account>(
        "status"_c.set("verified")
    ) | where("balance"_c > 2000.0);

    auto update3_result = update3(conn);
    if (!update3_result) {
      return false;
    }

    // Verify the changes persisted by reading back the data
    auto read_result = sqlgen::read<std::vector<Account>>(conn);
    if (!read_result) {
      return false;
    }

    auto accounts = read_result.value();

    // Verify account 1: balance should be 2500.0, status should be "verified" (from update3)
    bool account1_correct = false;
    for (const auto& acc : accounts) {
      if (acc.account_id.value == 1) {
        account1_correct = (acc.balance == 2500.0 && acc.status == "verified");
        break;
      }
    }

    // Verify account 2: balance should be 3000.0, status should be "verified" (from update3)
    bool account2_correct = false;
    for (const auto& acc : accounts) {
      if (acc.account_id.value == 2) {
        account2_correct = (acc.balance == 3000.0 && acc.status == "verified");
        break;
      }
    }

    // Verify account 3: balance should be 1500.0, status should be "active" (unchanged)
    bool account3_correct = false;
    for (const auto& acc : accounts) {
      if (acc.account_id.value == 3) {
        account3_correct = (acc.balance == 1500.0 && acc.status == "active");
        break;
      }
    }

    return account1_correct && account2_correct && account3_correct;

  } catch (...) {
    return false;
  }
}

}  // namespace update_set_operations

