 * Returns a vector of SupProd structs, where each struct contains the name of a supplier and the name of a product, if any.
 */
std::vector<SupProd> full_join_suppliers_products() {
  auto db = sqlgen::sqlite::connect("test_db.sqlite");

  return sqlgen::select_from<Supplier>(db)
    | sqlgen::full_join<Product>(
        sqlgen::col<&Supplier::supplier_id> == sqlgen::col<&Product::supplier_id>
      )
    | sqlgen::to<SupProd>(
        sqlgen::col<&Supplier::name>,
        sqlgen::col<&Product::name>
      )
    | sqlgen::vector;
}

}  // namespace full_join_suppliers_products
```

The implementation:
1. **Connects** to the SQLite database "test_db.sqlite" using `sqlgen::sqlite::connect`
2. **Selects from** the Supplier table using `sqlgen::select_from<Supplier>`
3. **Performs FULL JOIN** with the Product table on matching supplier_ids using `sqlgen::full_join<Product>`
4. **Maps the results** to the SupProd struct using `sqlgen::to<SupProd>`, selecting the supplier name and product name
5. **Collects results** into a vector using `sqlgen::vector`

The FULL JOIN will include all suppliers (even those without products) and all products (even those without matching suppliers), with `std::optional<std::string>` handling the nullable product_name field.

