#include <sqlgen/sqlite.hpp>
#include <vector>

namespace select_from_read_to_vector {

struct Book {
  sqlgen::PrimaryKey<int> book_id;
  std::string title;
  int pages;
};

/**
 * description: select_from_read_to_vector.
 * This function demonstrates how to read data from a table using sqlgen read API and store it in a vector.
 * It returns a vector of Book structs, where each struct contains the book_id, title, and pages.
 * Returns: std::vector<Book>, ordered by pages in descending order.
 */
std::vector<Book> select_from_read_to_vector() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to database, select from Book table, order by pages descending, and convert to vector
  return sqlite::connect()
      .and_then(select_from<Book>() | order_by("pages"_c.desc()) | to<std::vector<Book>>)
      .value();
}

}  // namespace select_from_read_to_vector
```

## Explanation:

1. **`using namespace sqlgen;`** and **`using namespace sqlgen::literals;`** - These bring in the necessary sqlgen functions and the literal operators (like `"pages"_c`)

2. **`sqlite::connect()`** - Creates a connection to an in-memory SQLite database

3. **`select_from<Book>()`** - Selects all columns from the Book table (inferred from the Book struct)

4. **`order_by("pages"_c.desc())`** - Orders the results by the `pages` column in descending order:
   - `"pages"_c` creates a column reference using the user-defined literal
   - `.desc()` makes it descending order

5. **`to<std::vector<Book>>`** - Converts the query results to a `std::vector<Book>`

6. **`.value()`** - Extracts the value from the `Result` type returned by `and_then()`

The function chains these operations together using the pipe operator `|` for the query building, and `.and_then()` for monadic error handling with the connection.

