21	TEST(sqlite, test_operations_with_nullable) {
22	  const auto people1 = std::vector<Person>(
23	      {Person{
24	           .id = 0, .first_name = "Homer", .last_name = "Simpson", .age = 45},
25	       Person{.id = 1, .first_name = "Bart", .last_name = "Simpson", .age = 10},
26	       Person{.id = 2, .first_name = "Hugo", .age = 10},
27	       Person{.id = 3, .first_name = "Lisa", .last_name = "Simpson", .age = 8},
28	       Person{
29	           .id = 4, .first_name = "Maggie", .last_name = "Simpson", .age = 0}});
30	
31	  using namespace sqlgen;
32	  using namespace sqlgen::literals;
33	
34	  struct Children {
35	    std::optional<int> id_plus_age;
36	    std::optional<int> age_times_2;
37	    std::optional<int> id_plus_2_minus_age;
38	    std::optional<std::string> full_name;
39	    std::string last_name_or_none;
40	  };
41	
42	  const auto get_children =
43	      select_from<Person>(
44	          ("id"_c + "age"_c) | as<"id_plus_age">,
45	          ("age"_c * 2) | as<"age_times_2">,
46	          ("id"_c + 2 - "age"_c) | as<"id_plus_2_minus_age">,
47	          concat(upper("last_name"_c), ", ", "first_name"_c) | as<"full_name">,
48	          coalesce(upper("last_name"_c), "none") | as<"last_name_or_none">) |
49	      where("age"_c < 18) | to<std::vector<Children>>;
50	
