```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

namespace create_index_basic {

struct Book {
  sqlgen::PrimaryKey<int> id;
  std::string title;
};

/**
 * This function demonstrates creating an index.
 */
inline auto create_index_basic() {
    using namespace sqlgen::literals;
    return sqlgen::create_index<"idx_book_title", Book>("title"_c);
}

}  // namespace create_index_basic
```

The implementation:
1. Defines the `Book` struct with a primary key `id` and a `title` field
2. Uses `sqlgen::literals` namespace to access the `_c` literal operator
3. Calls `sqlgen::create_index` with:
   - Template parameter `"idx_book_title"` for the index name
   - Template parameter `Book` for the table struct
   - Runtime parameter `"title"_c` to specify the column to index
4. Returns the create index query object that can be chained with other sqlgen operations

