          "product_name"_p | as<"product_name">,
          "category"_p | as<"category">,
          sum("price"_p * "quantity"_s) | as<"total_sales">
      ) |
      inner_join<Sales, "s">("product_id"_p == "product_id"_s) |
      group_by("product_id"_p, "product_name"_p, "category"_p) |
      order_by("total_sales"_c.desc()) |
      limit(limit_count) |
      to<std::vector<TopProduct>>;

