#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace get_top_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string product_name;
  std::string category;
  double price;
};

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Date sale_date;
};

struct TopProduct {
  int product_id;
  std::string product_name;
  std::string category;
  double total_sales;
};

/**
 * Description: This function retrieves the top products based on total sales.
 * Returns: std::vector<TopProduct>.
 */
std::vector<TopProduct> get_top_products(size_t limit_count = 10) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Build the query:
  // SELECT p.product_id, p.product_name, p.category,
  //        SUM(p.price * s.quantity) as total_sales
  // FROM Product p
  // INNER JOIN Sales s ON p.product_id = s.product_id
  // GROUP BY p.product_id, p.product_name, p.category
  // ORDER BY total_sales DESC
  // LIMIT limit_count
  const auto query =
      select_from<Product, "p">(
          "product_id"_p | as<"product_id">,
          "product_name"_p | as<"product_name">,
          "category"_p | as<"category">,
          sum("price"_p * "quantity"_s) | as<"total_sales">
      ) |
      inner_join<Sales, "s">("product_id"_p == "product_id"_s) |
      group_by("product_id"_p, "product_name"_p, "category"_p) |
      order_by("total_sales"_c.desc()) |
      limit(limit_count) |
      to<std::vector<TopProduct>>;

  // Connect to the SQLite database and execute the query
  const auto result = sqlite::connect("test_db.sqlite")
                          .and_then(query)
                          .value();

  return result;
}

}  // namespace get_top_products

