Here is the complete implementation of the `get_top_products.hpp` file:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace get_top_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string product_name;
  std::string category;
  double price;
};

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Date sale_date;
};

struct TopProduct {
  int product_id;
  std::string product_name;
  std::string category;
  double total_sales;
};

/**
 * Description: This function retrieves the top products based on total sales.
 * Returns: std::vector<TopProduct>.
 */
std::vector<TopProduct> get_top_products(size_t limit_count = 10) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Build the query:
  // SELECT p.product_id, p.product_name, p.category,
  //        SUM(p.price * s.quantity) as total_sales
  // FROM Product p
  // INNER JOIN Sales s ON p.product_id = s.product_id
  // GROUP BY p.product_id, p.product_name, p.category
  // ORDER BY total_sales DESC
  // LIMIT limit_count
  const auto query =
      select_from<Product, "p">(
          "product_id"_p | as<"product_id">,
          "product_name"_p | as<"product_name">,
          "category"_p | as<"category">,
          sum("price"_p * "quantity"_s) | as<"total_sales">
      ) |
      inner_join<Sales, "s">("product_id"_p == "product_id"_s) |
      group_by("product_id"_p, "product_name"_p, "category"_p) |
      order_by("total_sales"_c.desc()) |
      limit(limit_count) |
      to<std::vector<TopProduct>>;

  // Connect to the SQLite database and execute the query
  const auto result = sqlite::connect("test_db.sqlite")
                          .and_then(query)
                          .value();

  return result;
}

}  // namespace get_top_products
```

## Key Implementation Details:

1. **Table Aliases**: Used `"p"` for Product table and `"s"` for Sales table, following sqlgen conventions

2. **Column Selection**: 
   - Selected `product_id`, `product_name`, and `category` from the Product table
   - Calculated `total_sales` using `sum("price"_p * "quantity"_s)` to compute the sum of price × quantity

3. **Join**: Used `inner_join` to connect Product and Sales tables on `product_id`

4. **Grouping**: Applied `group_by` on all non-aggregated columns (`product_id`, `product_name`, `category`)

5. **Ordering**: Sorted results by `total_sales` in descending order using `.desc()`

6. **Limiting**: Applied the `limit_count` parameter to restrict results to top N products

7. **Database Connection**: Connected to "test_db.sqlite" using `sqlite::connect("test_db.sqlite")`

8. **Result Conversion**: Used `to<std::vector<TopProduct>>` to convert query results into the desired vector of TopProduct structs

The generated SQL will be equivalent to:
```sql
SELECT p.product_id, p.product_name, p.category, SUM(p.price * s.quantity) AS total_sales
FROM Product p
INNER JOIN Sales s ON p.product_id = s.product_id
GROUP BY p.product_id, p.product_name, p.category
ORDER BY total_sales DESC
LIMIT 10;
```

