#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

namespace order_by_descending {

struct Score {
  sqlgen::PrimaryKey<int> id;
  int points;
};

/**
 * This function demonstrates ORDER BY DESC.
 * Returns: std::string.
 */
inline std::string order_by_descending() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Construct a query to select scores ordered by points in descending order
    const auto query = sqlgen::read<std::vector<Score>> |
                       order_by("points"_c.desc());

    // Convert the query to SQL string using sqlite dialect
    return sqlgen::sqlite::to_sql(query);
}

}  // namespace order_by_descending
```

## Explanation:

1. **Define a `Score` struct**: The struct is already defined with `sqlgen::PrimaryKey<int> id` and `int points` fields.

2. **Construct the query**: Using sqlgen's fluent API:
   - `sqlgen::read<std::vector<Score>>` - Creates a read query for the Score table
   - `"points"_c` - Uses the column literal to reference the "points" column
   - `.desc()` - Calls the `desc()` method on the column to specify descending order
   - `order_by(...)` - Wraps the descending column specification in the `order_by` function
   - Uses the pipe operator `|` to chain the ordering to the read query

3. **Return the SQL string**: `sqlgen::sqlite::to_sql(query)` converts the query object to an actual SQL string using the SQLite dialect.

The generated SQL would be something like: `SELECT id, points FROM Score ORDER BY points DESC`

