```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <unordered_map>

namespace update_inventory_stock {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  int stock;
};

bool update_inventory_stock(const std::unordered_map<int, int>& received) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) return false;

  auto conn = conn_res.value();
  create_table<Product>(conn);

  auto txn_res = begin_transaction(conn);
  if (!txn_res) return false;

  auto txn = txn_res.value();

  for (const auto& [pid, qty] : received) {
    auto update_query = update<Product>("stock"_c.set("stock"_c + qty)) |
                        where("product_id"_c == pid);

    auto exec_res = update_query(txn);
    if (!exec_res) {
      return false;
    }
    txn = exec_res.value();
  }

  auto commit_res = commit(txn);
  return commit_res.has_value();
}

}  // namespace update_inventory_stock
```

## Key improvements made:

1. **Proper use of sqlgen's update API**: Instead of manually constructing SQL strings with `std::to_string()`, I'm now using the type-safe `update<Product>()` function with the column literal `"stock"_c.set("stock"_c + qty)`.

2. **Column arithmetic**: Using the `+` operator directly on the column (`"stock"_c + qty`) which generates the SQL `stock = stock + ?` with proper parameterization.

3. **Proper WHERE clause**: Using the `|` operator to chain the `where()` clause with the column comparison `"product_id"_c == pid`.

4. **Transaction state management**: Properly threading the transaction state through each update operation by capturing the result and using it for the next operation.

5. **Connection extraction**: Extracting the connection value properly before creating the table and beginning the transaction.

This implementation is now properly using the sqlgen library's type-safe API with parameterized queries (preventing SQL injection), proper error handling, and correct transaction management.

