14	Result<Ref<Connection>> exec(const Ref<Connection>& _conn,
15	                             const std::string& _sql) {
16	  return _conn->execute(_sql).transform([&](const auto&) { return _conn; });
17	}
18	
19	template <class Connection>
20	  requires is_connection<Connection>
21	Result<Ref<Connection>> exec(const Result<Ref<Connection>>& _res,
22	                             const std::string& _sql) {
23	  return _res.and_then([&](const auto& _conn) { return exec(_conn, _sql); });
24	}
25	
26	struct Exec {
27	  auto operator()(const auto& _conn) const { return exec(_conn, sql_); }
28	
29	  std::string sql_;
30	};
31	
32	inline auto exec(const std::string& _sql) { return Exec{.sql_ = _sql}; }
33	
34	};  // namespace sqlgen
