```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

namespace left_join_explicit {

struct User {
  sqlgen::PrimaryKey<int> id;
  std::string name;
};

struct Post {
  sqlgen::PrimaryKey<int> id;
  int user_id;
  std::string title;
};

/**
 * This function demonstrates a LEFT JOIN.
 * Returns: std::string.
 */
inline std::string left_join_explicit() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Construct a LEFT JOIN query: select users and their posts
  // Users without posts will still appear with NULL post fields
  const auto query = select_from<User, "t1">(
    "id"_t1 | as<"user_id">,
    "name"_t1 | as<"user_name">,
    "id"_t2 | as<"post_id">,
    "title"_t2 | as<"post_title">
  ) | left_join<Post, "t2">("id"_t1 == "user_id"_t2);

  // Generate and return the SQL string
  return to_sql(query);
}

}  // namespace left_join_explicit
```

This implementation:

1. **Defines structs**: `User` and `Post` with appropriate fields (already provided in your template)
2. **Uses LEFT JOIN**: Joins `User` (t1) with `Post` (t2) on the condition `t1.id = t2.user_id`
3. **Uses table aliases**: `"t1"` for User and `"t2"` for Post
4. **Uses column literals**: `"id"_t1`, `"name"_t1`, etc., from `sqlgen::literals`
5. **Returns SQL string**: Uses `to_sql()` to convert the query to a SQL string

The generated SQL will be:
```sql
SELECT t1."id" AS "user_id", t1."name" AS "user_name", t2."id" AS "post_id", t2."title" AS "post_title" 
FROM "User" t1 
LEFT JOIN "Post" t2 ON t1."id" = t2."user_id"
```

This demonstrates a proper LEFT JOIN where all users are returned, along with their associated posts if they exist.

