230	
231	template <rfl::internal::StringLiteral _name,
232	          rfl::internal::StringLiteral _alias>
233	struct ToTranspilationType<sqlgen::Col<_name, _alias>> {
234	  using Type = transpilation::Col<_name, _alias>;
235	
236	  Type operator()(const auto&) const noexcept {
237	    return transpilation::Col<_name, _alias>{};
238	  }
239	};
240	}  // namespace transpilation
241	
242	}  // namespace sqlgen
