6	#include "../dynamic/Statement.hpp"
7	#include "../transpilation/to_sql.hpp"
8	
9	namespace sqlgen::sqlite {
10	
11	/// Transpiles a dynamic general SQL statement to the sqlite dialect.
12	std::string to_sql_impl(const dynamic::Statement& _stmt) noexcept;
13	
14	/// Transpiles any  SQL statement to the sqlite dialect.
15	template <class T>
16	std::string to_sql(const T& _t) noexcept {
17	  if constexpr (std::is_same_v<std::remove_cvref_t<T>, dynamic::Statement>) {
18	    return to_sql_impl(_t);
19	  } else {
20	    return to_sql_impl(transpilation::to_sql(_t));
21	  }
22	}
23	
24	}  // namespace sqlgen::sqlite
