30	
31	  sqlgen::write(conn, people1);
32	
33	  using namespace sqlgen;
34	  using namespace sqlgen::literals;
35	
36	  const auto query =
37	      update<Person>("first_name"_c.set("last_name"_c), "age"_c.set(100)) |
38	      where("first_name"_c == "Hugo");
39	
40	  query(conn).value();
41	
42	  const auto people2 = sqlgen::read<std::vector<Person>>(conn).value();
