40	template <class... Ts>
41	auto coalesce(const Ts&... _ts) {
42	  static_assert(sizeof...(_ts) > 1,
43	                "coalesce(...) must have at least two inputs.");
44	  using Type = rfl::Tuple<typename transpilation::ToTranspilationType<
45	      std::remove_cvref_t<Ts>>::Type...>;
