  sqlgen::PrimaryKey<int> project_id;
  std::string name;
  int day;
  int month;
  int year;
  int hour;
  int minute;
  int second;
  double duration_days;
};

/**
 * Description: This function tracks time metrics for each project, including day, month, year, hour, minute, second, and duration in days.
 * Returns: std::vector<TimeMetrics>.
 */
std::vector<TimeMetrics> project_time_tracking() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Create the query that extracts time components and computes duration
  const auto query =
      select_from<Project, "p">(
          "project_id"_t1 | as<"project_id">,
          "name"_t1 | as<"name">,
          day("start_time"_t2) | as<"day">,
          month("start_time"_t2) | as<"month">,
          year("start_time"_t2) | as<"year">,
          hour("start_time"_t2) | as<"hour">,
          minute("start_time"_t2) | as<"minute">,
          second("start_time"_t2) | as<"second">,
          days_between("start_time"_t2, "end_time"_t2) | as<"duration_days">) |
      inner_join<TimeLog, "t2">("project_id"_t1 == "project_id"_t2) |
      to<std::vector<TimeMetrics>>;

  // Connect to the database and execute the query
  auto result = sqlite::connect("test_db.sqlite")
                    .and_then(query)
                    .value();

  return result;
}

}  // namespace project_time_tracking

