#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace group_by_with_aggregations {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
};

struct Post {
  sqlgen::PrimaryKey<int> post_id;
  int user_id;
  std::string content;
};

struct Stats {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
  int post_count;
  std::optional<double> avg_length;
};

/**
 * Description: This function retrieves user statistics including post count and average post length.
 * Returns: std::vector<Stats>.
 */
std::vector<Stats> group_by_with_aggregations() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Build the query:
  // SELECT u.user_id, u.name, COUNT(*) as post_count, AVG(LENGTH(p.content)) as avg_length
  // FROM User u
  // INNER JOIN Post p ON u.user_id = p.user_id
  // GROUP BY u.user_id, u.name
  const auto query =
      select_from<User, "u">(
          "user_id"_u | as<"user_id">,
          "name"_u | as<"name">,
          count() | as<"post_count">,
          avg(length("content"_p)) | as<"avg_length">) |
      inner_join<Post, "p">("user_id"_u == "user_id"_p) |
      group_by("user_id"_u, "name"_u) |
      to<std::vector<Stats>>;

  // Execute the query and return the results
  return conn.and_then(query).value();
}

}  // namespace group_by_with_aggregations
```

The implementation:
1. **Connects to SQLite**: Uses `sqlite::connect("test_db.sqlite")` to connect to the database
2. **Builds the query**: Uses the fluent API from sqlgen:
   - `select_from<User, "u">` - selects from the User table with alias "u"
   - Selects the columns: user_id, name, COUNT(*), and AVG(LENGTH(content))
   - `inner_join<Post, "p">` - joins with Post table on user_id
   - `group_by` - groups by user_id and name
   - `to<std::vector<Stats>>` - converts results to the Stats structure
3. **Returns results**: Executes the query and returns the vector of Stats

The query uses:
- Column literals with table aliases (`_u` and `_p` suffixes for table aliases)
- `count()` for counting posts
- `avg(length(...))` for calculating average content length
- `as<"name">` to alias the result columns to match the Stats struct fields

