  int age;
};

/**
 * This function demonstrates using read_to_select_from.
 * Returns: std::string.
 */
inline std::string read_to_select_from_usage() {
  using namespace sqlgen::literals;

  // Create a WHERE condition: age > 18
  const auto where_condition = "age"_c > 18;

  // Create a LIMIT of 10
  const auto limit_value = sqlgen::limit(10);

  // Use read_to_select_from to generate the SELECT statement
  const auto select_from = sqlgen::transpilation::read_to_select_from<User>(
      where_condition, limit_value);

  // Convert to SQL string using a SQLite connection
  const auto conn = sqlgen::sqlite::connect().value();
  const auto sql = conn->to_sql(select_from);

  return sql;
}

}  // namespace read_to_select_from_usage
```

## Explanation:

1. **User struct**: Already defined with `id`, `name`, and `age` fields
2. **Column literals**: Using `sqlgen::literals` namespace to use the `_c` suffix for column references
3. **WHERE condition**: `"age"_c > 18` creates a condition for `age > 18`
4. **LIMIT**: `sqlgen::limit(10)` creates a limit of 10 records
5. **read_to_select_from**: Generates a `dynamic::SelectFrom` object with:
   - Template parameter `User` specifies the table structure
   - `where_condition` provides the WHERE clause
   - `limit_value` provides the LIMIT clause
6. **Convert to SQL**: Creates a SQLite connection and uses `to_sql()` to convert the `SelectFrom` object to a SQL string
7. **Return**: Returns the generated SQL string

The resulting SQL should be something like:
```sql
SELECT "id", "name", "age" FROM "User" WHERE "age" > 18 LIMIT 10
```

